import React, {Component} from 'react';
import {reportUtils} from "../helper/reportUtils";

class WidalSection extends Component {

    constructor(props) {
        super(props);
        this.sectionRef = React.createRef();
        this.state = {collapsed: true};
    }

    componentDidUpdate(prevProps) {
        if (this.props.expandKey && this.props.expandKey !== prevProps.expandKey) {
            this.setState({collapsed: false});
        }
        if (this.props.collapseKey !== prevProps.collapseKey) {
            this.setState({collapsed: true});
        }
    }

    toggleCollapse = () => {
        this.setState(prev => ({collapsed: !prev.collapsed}));
    };

    scrollSectionToTopAndRefocus = (inputEl) => {
        const anchor = document.getElementById(this.props.id);
        inputEl.blur();
        if (anchor) anchor.scrollIntoView({behavior: 'smooth', block: 'start'});
        setTimeout(() => inputEl.focus({ preventScroll: true }), 350);
    };

    handleKeyDown = (e) => {
        const navH = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--navbar-height')) || 60;
        const rect = e.target.getBoundingClientRect();
        if (rect.top > window.innerHeight || rect.bottom < navH) {
            const target = e.target;
            setTimeout(() => this.scrollSectionToTopAndRefocus(target), 0);
        }

        if (e.key !== 'Enter') return;
        e.preventDefault();
        if (!this.sectionRef.current) return;
        const inputs = Array.from(this.sectionRef.current.querySelectorAll('input:not([disabled])'));
        const idx = inputs.indexOf(e.target);
        if (idx !== -1 && idx < inputs.length - 1) {
            const nextInput = inputs[idx + 1];
            nextInput.focus({ preventScroll: true });
            nextInput.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } else if (idx === inputs.length - 1 && this.props.onAdvanceSection) {
            this.props.onAdvanceSection(this.props.id);
        }
    };

    onChange = (e) => {
        const {name, value} = e.target;
        const {id, column_index} = JSON.parse(name);
        const state = this.props.patientReport || {};
        const row = state[id] || {};

        this.props.onPatientReportChanged(
            this.props.id,
            {
                [id]: {
                    ...row,
                    [column_index]: value
                }
            }
        );
    };

    getInput = (state, data, findingsColumn) => {
        const {id, type, values} = data;
        const value = state[id] || {};

        switch (type) {
            case 'free':
                return findingsColumn.map((column, i) => {
                    return <td key={column}>
                        <input
                            onChange={this.onChange}
                            onKeyDown={this.handleKeyDown}
                            name={JSON.stringify({id, column_index: i})}
                            value={value[i] || ''}
                            type='text'/>
                    </td>
                });
            case 'radio': {
                const optionValues = values.filter(v => v !== reportUtils.EMPTY_SELECT_VALUE);

                if (this.props.preview) {
                    return findingsColumn.map((column, i) => {
                        const cellVal = value[i] || '';
                        return <td key={column}>{cellVal !== reportUtils.EMPTY_SELECT_VALUE ? cellVal : ''}</td>;
                    });
                }

                if (optionValues.length <= 8) {
                    return findingsColumn.map((column, i) => {
                        const cellSelected = value[i] || reportUtils.EMPTY_SELECT_VALUE;
                        return <td key={column}>
                            <div className="option-group">
                                {optionValues.map(opt => (
                                    <button
                                        key={opt}
                                        type="button"
                                        data-color-intent={reportUtils.getOptionColorIntent(opt)}
                                        className={`option-btn${cellSelected === opt ? ' option-btn--selected' : ''}`}
                                        onClick={() => {
                                            const next = cellSelected === opt ? reportUtils.EMPTY_SELECT_VALUE : opt;
                                            const currentState = this.props.patientReport || {};
                                            const row = currentState[id] || {};
                                            this.props.onPatientReportChanged(this.props.id, {[id]: {...row, [i]: next}});
                                        }}
                                    >{opt}</button>
                                ))}
                            </div>
                        </td>;
                    });
                }

                return findingsColumn.map((column, i) => {
                    return <td key={column}>
                        <select
                            onChange={this.onChange}
                            name={JSON.stringify({id, column_index: i})}
                            value={value[i] || reportUtils.EMPTY_SELECT_VALUE}>
                            {values.map((val, j) => <option key={j} value={val}>{val}</option>)}
                        </select>
                    </td>;
                });
            }
            default:
                return <td/>;
        }
    };

    getRow = (state, findingsColumn, data) => {
        return <tbody>
        {data.map(row => {
            const allColumnEmpty = !reportUtils.hasReportData(state[row.id] || {});

            return <tr hidden={this.props.preview && allColumnEmpty} key={row.id}>
                <td>{row.name}</td>
                {this.getInput(state, row, findingsColumn)}
            </tr>
        })}
        </tbody>;
    };

    onClear = () => {
        this.props.onClear(this.props.id);
    };

    render() {
        const {name, findings_column, data} = this.props.placeholder;
        const preview = this.props.preview;
        const state = this.props.patientReport || {};
        const sectionIsEmpty = !reportUtils.hasReportData(state);
        const isCollapsed = !preview && this.state.collapsed;

        return (
            <section ref={this.sectionRef} hidden={preview && sectionIsEmpty} className='report-section no-page-break'>
                <span id={this.props.id} className='anchor'/>
                <div className="section-heading">
                    {!preview
                        ? <button className="section-heading-toggle" onClick={this.toggleCollapse}>
                            <h4>{name}</h4>
                            <span className="collapse-icon">{isCollapsed ? '▶' : '▼'}</span>
                          </button>
                        : <h4>{name}</h4>
                    }
                    {!preview && <button title="Clear this report" className='btn btn-sm btn-outline-danger'
                                         onClick={this.onClear}>Clear section</button>}
                </div>
                {!isCollapsed && <table className={preview ? 'report-table widal-table' : 'table table-bordered report-table widal-table'}>
                    <colgroup>
                        <col className="col-antigen" />
                        {findings_column.map((_, i) => <col key={i} className="col-dilution" />)}
                    </colgroup>
                    <thead className={preview ? '' : 'thead-dark'}>
                    <tr>
                        <th>Test name</th>
                        <th colSpan={findings_column.length}>Result</th>
                    </tr>
                    </thead>
                    <thead className={preview ? '' : 'thead-light'}>
                    <tr>
                        <th rowSpan='2'>Antigen</th>
                        <th colSpan={findings_column.length}>Dilution</th>
                    </tr>
                    <tr>
                        {findings_column.map(column => <th key={column}>{column}</th>)}
                    </tr>
                    </thead>
                    {this.getRow(state, findings_column, data)}
                </table>}
            </section>
        );
    }
}

export default WidalSection;
