import { collection, addDoc, getDocs, getDoc, doc, deleteDoc, query, orderBy, limit } from 'firebase/firestore';
import { db } from './firebase';

const COLLECTION = 'reports';

/**
 * Save a report payload to Firestore.
 * Stores searchable top-level fields alongside the full data blob.
 */
export async function saveReportToCloud(payload) {
    const { patientInfo = {} } = payload;
    const document = {
        patientNameDisplay: patientInfo.name || '',
        patientName: (patientInfo.name || '').toLowerCase(),
        age: String(patientInfo.age || ''),
        sex: patientInfo.gender || '',
        date: patientInfo.date || '',
        savedAt: new Date().toISOString(),
        data: payload,
    };
    return addDoc(collection(db, COLLECTION), document);
}

/**
 * Delete a report from Firestore by document ID.
 */
export async function deleteReportFromCloud(id) {
    return deleteDoc(doc(db, COLLECTION, id));
}

/**
 * Fetch a single report by its Firestore document ID.
 */
export async function getReportById(id) {
    const snap = await getDoc(doc(db, COLLECTION, id));
    if (!snap.exists()) return null;
    return { id: snap.id, ...snap.data() };
}

/**
 * Fetch the most recent 500 reports for client-side search/sort.
 */
export async function fetchReports() {
    const q = query(
        collection(db, COLLECTION),
        orderBy('savedAt', 'desc'),
        limit(500)
    );
    const snapshot = await getDocs(q);
    return snapshot.docs.map(d => ({ id: d.id, ...d.data() }));
}

// ---------------------------------------------------------------------------
// Client-side fuzzy search
// ---------------------------------------------------------------------------

const MONTH_NAMES = [
    'january','february','march','april','may','june',
    'july','august','september','october','november','december',
];
const MONTH_ABBR = MONTH_NAMES.map(m => m.slice(0, 3));

function tokenMatchesRecord(token, record) {
    const t = token.toLowerCase();
    const name = (record.patientName || '').toLowerCase();
    const age  = String(record.age || '');
    const sex  = (record.sex || '').toLowerCase();
    const date = String(record.date || '');

    // Name — substring match
    if (name.includes(t)) return true;

    // Age — exact match
    if (age === t) return true;

    // Sex — M / F / Male / Female
    if ((t === 'm' || t === 'male')   && (sex === 'm' || sex === 'male'))   return true;
    if ((t === 'f' || t === 'female') && (sex === 'f' || sex === 'female')) return true;

    // Date — only attempt digit/substring match when the token contains a digit
    // (avoids the `.includes("")` always-true bug for purely alpha tokens)
    if (/\d/.test(t)) {
        const tDigits = t.replace(/\D/g, '');
        const dDigits = date.replace(/\D/g, '');
        if (tDigits && dDigits.includes(tDigits)) return true;
        if (date.toLowerCase().includes(t)) return true;
    }

    // Month name / abbreviation → numeric month in date string
    const abbr = t.slice(0, 3);
    const monthIdx = MONTH_ABBR.indexOf(abbr);
    if (monthIdx !== -1) {
        const mm = String(monthIdx + 1).padStart(2, '0');
        if (date.includes(`-${mm}-`) || date.includes(`/${mm}/`) || date.includes(`-${mm}/`)) return true;
    }

    return false;
}

/**
 * OR-semantics: a record is included if ANY space-separated token matches
 * any of its fields. Empty query returns all records.
 *
 * Examples:
 *   "john"        → records whose name contains "john"
 *   "john july"   → records whose name contains "john" OR "july"
 *   "john 25"     → records whose name contains "john" OR whose age is "25"
 */
export function searchReports(records, queryStr) {
    if (!queryStr || !queryStr.trim()) return records;
    const tokens = queryStr.trim().split(/\s+/).filter(Boolean);
    return records.filter(r => tokens.some(t => tokenMatchesRecord(t, r)));
}
