import React, { Component } from 'react';
import axios from 'axios';
import { pdf } from '@react-pdf/renderer';
import QRCode from 'qrcode';
import ReportPDF from './ReportPDF';
import { loadSettings } from '../helper/settingsUtils';
import { getReportById } from '../services/cloudStorage';

// iOS Safari cannot render PDFs inside an <iframe> — detect it so we can
// show a direct-open button instead.
function isIOS() {
    return /iPad|iPhone|iPod/.test(navigator.userAgent) ||
        (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

class ReportPreview extends Component {
    constructor(props) {
        super(props);
        this.state = {
            loading: true,
            error: '',
            patientInfo: {},
            patientReport: {},
            dataPlaceholder: null,
            generatingPdf: false,
            pdfUrl: null,
        };
        this._pdfUrl = null;
    }

    componentDidMount() {
        const { id } = this.props.match.params;

        Promise.all([
            getReportById(id),
            axios.get(process.env.PUBLIC_URL + '/assets/dataPlaceholder.json'),
        ])
            .then(([record, schemaRes]) => {
                if (!record) {
                    this.setState({ loading: false, error: 'Report not found. It may have been deleted or the link is invalid.' });
                    return;
                }
                const data = record.data || {};
                const patientInfo = data.patientInfo || {};
                const patientReport = data.patientReport || {};
                const dataPlaceholder = schemaRes.data;
                this.setState({
                    loading: false,
                    patientInfo,
                    patientReport,
                    dataPlaceholder,
                    generatingPdf: true,
                }, () => this.autoGeneratePdf(id, patientInfo, patientReport, dataPlaceholder));
            })
            .catch(() => {
                this.setState({ loading: false, error: 'Failed to load report. Please check your connection and try again.' });
            });
    }

    componentWillUnmount() {
        if (this._pdfUrl) URL.revokeObjectURL(this._pdfUrl);
    }

    autoGeneratePdf = async (id, patientInfo, patientReport, dataPlaceholder) => {
        const settings = loadSettings();
        try {
            let qrDataUrl = null;
            if (settings.saveToCloud) {
                try {
                    // Use current page URL as base so it works on any domain/subpath
                    const base = window.location.href.split('#')[0];
                    const reportUrl = `${base}#/report/${id}`;
                    qrDataUrl = await QRCode.toDataURL(reportUrl, { width: 120, margin: 1 });
                } catch (e) { /* proceed without QR */ }
            }

            const blob = await pdf(
                <ReportPDF
                    patientInfo={patientInfo}
                    patientReport={patientReport}
                    dataPlaceholder={dataPlaceholder}
                    qrDataUrl={qrDataUrl}
                    settings={settings}
                    showLabHeader={true}
                />
            ).toBlob();

            const url = URL.createObjectURL(blob);
            this._pdfUrl = url;

            if (isIOS()) {
                // On iOS Safari, navigate directly to the blob URL — Safari opens it
                // in its native PDF viewer. An iframe with a blob URL is blocked on iOS.
                window.location.href = url;
            } else {
                this.setState({ generatingPdf: false, pdfUrl: url });
            }
        } catch (e) {
            this.setState({ generatingPdf: false, error: 'Failed to generate PDF.' });
        }
    };

    printPage = () => {
        const { pdfUrl } = this.state;
        if (!pdfUrl) return;
        const iframe = document.createElement('iframe');
        iframe.style.cssText = 'position:fixed;width:0;height:0;border:0;opacity:0;';
        document.body.appendChild(iframe);
        iframe.src = pdfUrl;
        iframe.onload = () => {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();
            setTimeout(() => document.body.removeChild(iframe), 60000);
        };
    };

    render() {
        const { loading, error, generatingPdf, pdfUrl } = this.state;

        if (loading || generatingPdf) {
            return (
                <div className="rp-shell">
                    <div className="rp-status">{loading ? 'Loading report…' : 'Generating PDF…'}</div>
                </div>
            );
        }

        if (error) {
            return (
                <div className="rp-shell">
                    <div className="rp-status rp-error">{error}</div>
                </div>
            );
        }

        if (pdfUrl) {
            // Full-screen embedded PDF (non-iOS only; iOS navigates directly via window.location.href)
            return (
                <iframe
                    src={pdfUrl}
                    title="Report PDF"
                    style={{ position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', border: 'none' }}
                />
            );
        }

        return null;
    }
}

export default ReportPreview;
