import React, {Component} from 'react';
import {dataActions} from "../actions/dataActions";
import {connect} from "react-redux";
import { pdf } from '@react-pdf/renderer';
import QRCode from 'qrcode';
import Section from "./Section";
import WidalSection from "./WidalSection";
import PatientInfo from "./PatientInfo";
import LoadModal from "./LoadModal";
import ReportPDF from './ReportPDF';
import SettingsModal from './Settings';
import getBsDateByAdDate from "../helper/nepaliDate";
import {utils} from "../helper/utils";
import {reportUtils} from "../helper/reportUtils";
import {loadSettings} from "../helper/settingsUtils";
import {saveReportToCloud, deleteReportFromCloud} from "../services/cloudStorage";

const DRAFT_STORAGE_KEY = 'jagdambaLabReportDraft';

/**
 * Try to detect the machine's LAN IP via WebRTC so QR codes work
 * when scanned from a phone on the same network.
 * Returns the first non-loopback IPv4 found, or null.
 */
function detectLanIp() {
    return new Promise((resolve) => {
        try {
            const pc = new RTCPeerConnection({ iceServers: [] });
            pc.createDataChannel('');
            const candidates = [];
            pc.onicecandidate = (e) => {
                if (!e.candidate) {
                    pc.close();
                    const ip = candidates.find(a =>
                        /^(\d{1,3}\.){3}\d{1,3}$/.test(a) &&
                        !a.startsWith('127.') && !a.startsWith('169.254'));
                    resolve(ip || null);
                    return;
                }
                // candidate string: "candidate:... <addr> <port> typ host ..."
                const parts = e.candidate.candidate.split(' ');
                if (parts[7] === 'host' && parts[4]) candidates.push(parts[4]);
            };
            pc.createOffer().then(o => pc.setLocalDescription(o)).catch(() => resolve(null));
            setTimeout(() => { try { pc.close(); } catch (_) {} resolve(null); }, 2000);
        } catch (_) { resolve(null); }
    });
}

const shortenSectionName = (name) =>
    name.replace(/\bEXAMINATION\b/g, 'EXAM').replace(/\s+TEST\s*$/g, '').trim();

class Home extends Component {

    getNepaliDate = () => {
        try {
            const dateObj = new Date();
            const month = dateObj.getMonth() + 1;
            const day = dateObj.getDate();
            const year = dateObj.getFullYear();
            const hour = dateObj.getHours();
            const minute = dateObj.getMinutes();
            const second = dateObj.getSeconds();
            const nepaliDate = getBsDateByAdDate(year, month, day);

            const pad = n => String(n).padStart(2, '0');
            return {
                date: `${nepaliDate['bsYear']}-${pad(nepaliDate['bsMonth'])}-${pad(nepaliDate['bsDate'])}`,
                time: utils.format('{} - {} - {}', hour, minute, second)
            };
        } catch (e) {
            return {};
        }
    };

    getInitialState = () => ({
        patientInfo: {...this.getNepaliDate(), gender: 'Not selected'},
        patientReport: {},
        activeSection: 'PATIENT_INFO',
        showFilledOnly: false,
        validationMessages: [],
        recoverableDraft: null,
        lastDraftSavedAt: null,
        loadError: '',
        sectionSearch: '',
        attemptedPreview: false,
        undoToast: null,
        sectionExpandKeys: {},
        showLoadModal: false,
        showSettingsModal: false,
        globalCollapseKey: 0,
        isPrinting: false,
        sidebarOpen: true,
        cloudSaveStatus: null, // null | 'saving' | 'saved' | 'error'
        cloudDocId: null,
        isDirty: false,   // true once any field is edited after loading from cloud
        lanIp: null,
        settings: loadSettings(),
    });

    constructor(props) {
        super(props);
        this.autoSaveTimer = null;
        this.undoTimer = null;
        this.state = this.getInitialState();
    }

    componentDidMount() {
        this.props.getDataPlaceholder();
        this.detectRecoverableDraft();
        document.addEventListener('keydown', this.handleGlobalKeyDown);
        this.updateNavbarHeight();
        detectLanIp().then(ip => { if (ip) this.setState({ lanIp: ip }); });
    }

    componentDidUpdate(prevProps, prevState) {
        if (prevState.patientInfo !== this.state.patientInfo || prevState.patientReport !== this.state.patientReport) {
            this.queueDraftSave();
        }
        this.updateNavbarHeight();
    }

    updateNavbarHeight = () => {
        const nav = document.getElementById('side_nav_bar');
        if (nav) {
            document.documentElement.style.setProperty('--navbar-height', `${nav.offsetHeight}px`);
        }
    };

    componentWillUnmount() {
        if (this.autoSaveTimer) clearTimeout(this.autoSaveTimer);
        if (this.undoTimer) clearTimeout(this.undoTimer);
        document.removeEventListener('keydown', this.handleGlobalKeyDown);
    }

    toggleSidebar = () => this.setState(prev => ({ sidebarOpen: !prev.sidebarOpen }));

    handleGlobalKeyDown = (e) => {
        if ((e.ctrlKey || e.metaKey) && e.key === 'p') {
            e.preventDefault();
            this.handlePrint();
        }
    };

    detectRecoverableDraft = () => {
        const rawDraft = localStorage.getItem(DRAFT_STORAGE_KEY);
        if (!rawDraft) return;

        try {
            const recoverableDraft = JSON.parse(rawDraft);
            if (recoverableDraft && (recoverableDraft.patientInfo || recoverableDraft.patientReport)) {
                this.setState({recoverableDraft});
            }
        } catch (e) {
            localStorage.removeItem(DRAFT_STORAGE_KEY);
        }
    };

    queueDraftSave = () => {
        if (this.autoSaveTimer) clearTimeout(this.autoSaveTimer);

        this.autoSaveTimer = setTimeout(() => {
            const payload = reportUtils.createSavedPayload(this.state);
            localStorage.setItem(DRAFT_STORAGE_KEY, JSON.stringify(payload));
            this.setState({lastDraftSavedAt: new Date().toLocaleTimeString(), recoverableDraft: null});
        }, 300);
    };

    restoreDraft = () => {
        const {recoverableDraft} = this.state;
        if (!recoverableDraft) return;

        this.setState({
            patientInfo: {...this.getInitialState().patientInfo, ...recoverableDraft.patientInfo},
            patientReport: recoverableDraft.patientReport || {},
            recoverableDraft: null,
            validationMessages: [],
            loadError: '',
            attemptedPreview: false,
        });
    };

    dismissDraft = () => {
        localStorage.removeItem(DRAFT_STORAGE_KEY);
        this.setState({recoverableDraft: null});
    };

    showUndoToast = (message, restoreFn) => {
        if (this.undoTimer) clearTimeout(this.undoTimer);
        this.undoTimer = setTimeout(() => {
            this.setState({undoToast: null});
        }, 5000);
        this.setState({undoToast: {message, restoreFn}});
    };

    applyUndo = () => {
        if (this.undoTimer) clearTimeout(this.undoTimer);
        const {undoToast} = this.state;
        if (undoToast && undoToast.restoreFn) undoToast.restoreFn();
        this.setState({undoToast: null});
    };

    dismissUndoToast = () => {
        if (this.undoTimer) clearTimeout(this.undoTimer);
        this.setState({undoToast: null});
    };

    handleSaveToPC = jsonData => {
        const fileData = JSON.stringify(jsonData, null, 2);
        const blob = new Blob([fileData], {type: "application/json"});
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        const patientName = this.state.patientInfo.name ? this.state.patientInfo.name.replace(/ /g, '-') : 'Unknown';
        const date = (this.state.patientInfo.date || '').replace(/ /g, '');
        const time = (this.state.patientInfo.time || '').replace(/ /g, '');

        link.download = utils.format('{}_{}_{}.json', patientName, date, time);
        link.href = url;
        link.click();
        URL.revokeObjectURL(url);
    };

    handleLoadFromPC = () => {
        const inputTag = document.createElement("input");
        inputTag.type = "file";
        inputTag.accept = ".json";
        inputTag.multiple = false;
        inputTag.onchange = this.loadData;
        inputTag.click();
    };

    handleOpenLoadModal = () => this.setState({ showLoadModal: true });
    handleCloseLoadModal = () => this.setState({ showLoadModal: false });

    handleOpenSettings = () => this.setState({ showSettingsModal: true });
    handleCloseSettings = () => {
        // Re-read all settings so the app reflects any changes made in the modal
        this.setState({ showSettingsModal: false, settings: loadSettings() });
    };

    handleDeleteFromCloud = () => {
        const { cloudDocId } = this.state;
        if (!cloudDocId) return;
        if (!window.confirm('Delete this report from the cloud? Local data will remain.')) return;
        deleteReportFromCloud(cloudDocId)
            .then(() => {
                // Clear the cloud link — local data stays untouched.
                // isDirty=true so the next Print creates a fresh cloud entry.
                this.setState({ cloudDocId: null, isDirty: true, cloudSaveStatus: null });
            })
            .catch(() => {
                alert('Failed to delete from cloud. Please try again.');
            });
    };

    handleSelectCloudRecord = (record) => {
        const data = record.data || {};
        this.setState({
            patientInfo: {...this.getInitialState().patientInfo, ...(data.patientInfo || {})},
            patientReport: data.patientReport || {},
            validationMessages: [],
            loadError: '',
            attemptedPreview: false,
            showLoadModal: false,
            cloudDocId: record.id,
            isDirty: false,  // loaded clean — don't re-save unless user edits something
        });
    };

    onPatientReportChanged = (reportName, result) => {
        const {dataPlaceholder} = this.props.dataReducer;

        this.setState(prevState => {
            const currentReport = prevState.patientReport[reportName] || {};
            let nextReport = {...currentReport, ...result};

            if (dataPlaceholder && dataPlaceholder[reportName]) {
                nextReport = reportUtils.applyAutoFill(dataPlaceholder[reportName], nextReport);
            }

            return {
                patientReport: {
                    ...prevState.patientReport,
                    [reportName]: nextReport
                },
                validationMessages: [],
                isDirty: true,
            };
        });
    };

    onPatientInfoChanged = (testId, testValue) => {
        this.setState(prevState => ({
            patientInfo: {
                ...prevState.patientInfo,
                [testId]: testValue
            },
            validationMessages: [],
            isDirty: true,
        }));
    };

    onClearSection = (reportName) => {
        const prevReport = this.state.patientReport[reportName];
        if (!reportUtils.hasReportData(prevReport)) return;

        const sectionName = this.props.dataReducer.dataPlaceholder?.[reportName]?.name || reportName;

        this.setState(prevState => ({
            patientReport: {
                ...prevState.patientReport,
                [reportName]: {}
            },
            validationMessages: []
        }));

        this.showUndoToast(`"${sectionName}" cleared.`, () => {
            this.setState(prevState => ({
                patientReport: {
                    ...prevState.patientReport,
                    [reportName]: prevReport
                }
            }));
        });
    };

    saveToCloud = (onComplete) => {
        // Skip immediately when offline — app works fully offline, just no QR code.
        if (!navigator.onLine) {
            if (onComplete) onComplete();
            return;
        }

        const payload = reportUtils.createSavedPayload(this.state);
        this.setState({ cloudSaveStatus: 'saving' });

        const savePromise = saveReportToCloud(payload);
        const timeoutPromise = new Promise((_, reject) =>
            setTimeout(() => reject(new Error('timeout')), 10000)
        );

        Promise.race([savePromise, timeoutPromise])
            .then((docRef) => {
                this.setState({ cloudSaveStatus: 'saved', cloudDocId: docRef.id, isDirty: false }, () => {
                    setTimeout(() => this.setState({ cloudSaveStatus: null }), 3000);
                    if (onComplete) onComplete();
                });
            })
            .catch(() => {
                this.setState({ cloudSaveStatus: 'error' });
                setTimeout(() => this.setState({ cloudSaveStatus: null }), 3000);
                if (onComplete) onComplete(); // always proceed to PDF even on failure
            });
    };

    loadData = (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = this.onReaderLoad;
        reader.readAsText(file);
    };

    onReaderLoad = (event) => {
        try {
            const data = JSON.parse(event.target.result);
            this.setState({
                patientInfo: {...this.getInitialState().patientInfo, ...(data.patientInfo || {})},
                patientReport: data.patientReport || {},
                validationMessages: [],
                loadError: '',
                attemptedPreview: false,
            });
        } catch (e) {
            this.setState({loadError: 'The selected file could not be loaded. Please choose a valid saved report JSON file.'});
        }
    };

    clearAll = () => {
        const hasData = reportUtils.hasReportData(this.state.patientInfo) || Object.values(this.state.patientReport).some(reportUtils.hasReportData);
        if (!hasData) return;

        const prevPatientInfo = this.state.patientInfo;
        const prevPatientReport = this.state.patientReport;

        localStorage.removeItem(DRAFT_STORAGE_KEY);
        this.setState(this.getInitialState());
        this.showUndoToast('All data cleared.', () => {
            this.setState({
                patientInfo: prevPatientInfo,
                patientReport: prevPatientReport,
            });
        });
    };

    handlePrint = () => {
        const validationMessages = reportUtils.validateReportState(this.state.patientInfo, this.state.patientReport);
        if (validationMessages.length > 0) {
            this.setState({ validationMessages, attemptedPreview: true });
            return;
        }
        this.setState({ validationMessages: [], attemptedPreview: false });
        this.printPage();
    };

    printPage = () => {
        const { settings, cloudDocId, isDirty } = this.state;
        const needsSave = settings.saveToCloud && (!cloudDocId || isDirty);

        // Show "Generating…" immediately, then defer the heavy PDF work so
        // React has a chance to render the loading state before the main
        // thread is blocked by yoga-layout's synchronous layout passes.
        this.setState({ isPrinting: true }, () => {
            setTimeout(() => {
                if (needsSave) {
                    this.saveToCloud(() => this.generateAndPrintPdf());
                } else {
                    this.generateAndPrintPdf();
                }
            }, 50);
        });
    };

    generateAndPrintPdf = async () => {
        const { settings, cloudDocId, lanIp } = this.state;
        const { dataPlaceholder } = this.props.dataReducer;

        try {
            // Build QR data URL when enabled, cloud save is on, and we have a record ID
            let qrDataUrl = null;
            if (settings.showQrInPdf && settings.saveToCloud && cloudDocId) {
                try {
                    const isLocalhost = ['localhost', '127.0.0.1'].includes(window.location.hostname);
                    let reportUrl;
                    if (isLocalhost && lanIp) {
                        const port = window.location.port || 3000;
                        const pathname = window.location.pathname;
                        reportUrl = `http://${lanIp}:${port}${pathname}#/report/${cloudDocId}`;
                    } else {
                        // Strip any existing hash, then append the report hash route.
                        // window.location.pathname handles subdirectory deployments
                        // (e.g. /jagdamba-pathology-lab-software/ on GitHub Pages)
                        // and custom domains (just /) automatically.
                        const base = window.location.href.split('#')[0];
                        reportUrl = `${base}#/report/${cloudDocId}`;
                    }
                    qrDataUrl = await QRCode.toDataURL(reportUrl, { width: 120, margin: 1 });
                } catch (e) {
                    // QR generation failed — proceed without it
                }
            }

            const blob = await pdf(
                <ReportPDF
                    patientInfo={this.state.patientInfo}
                    patientReport={this.state.patientReport}
                    dataPlaceholder={dataPlaceholder}
                    qrDataUrl={qrDataUrl}
                    settings={settings}
                />
            ).toBlob();

            const url = URL.createObjectURL(blob);
            const iframe = document.createElement('iframe');
            iframe.style.cssText = 'position:fixed;width:0;height:0;border:0;opacity:0;';
            document.body.appendChild(iframe);
            iframe.src = url;
            iframe.onload = () => {
                iframe.contentWindow.focus();
                iframe.contentWindow.print();
                setTimeout(() => {
                    document.body.removeChild(iframe);
                    URL.revokeObjectURL(url);
                }, 60000);
            };
        } finally {
            this.setState({ isPrinting: false });
        }
    };

    setActiveSection = (activeSection) => {
        this.setState(prev => ({
            activeSection,
            sectionExpandKeys: {
                ...prev.sectionExpandKeys,
                [activeSection]: (prev.sectionExpandKeys[activeSection] || 0) + 1,
            },
        }));
        // Wait for expand re-render, then scroll to section top and focus first empty input
        setTimeout(() => {
            const anchor = document.getElementById(activeSection);
            if (anchor) anchor.scrollIntoView({behavior: 'smooth', block: 'start'});
            setTimeout(() => {
                const anchor2 = document.getElementById(activeSection);
                if (!anchor2) return;
                const sectionEl = anchor2.parentElement;
                if (!sectionEl) return;
                const inputs = Array.from(sectionEl.querySelectorAll('input:not([disabled]), select:not([disabled])'));
                for (const input of inputs) {
                    if (!input.value || input.value === reportUtils.EMPTY_SELECT_VALUE) {
                        input.focus();
                        break;
                    }
                }
            }, 350);
        }, 80);
    };

    advanceToNextSection = (currentId) => {
        const {dataPlaceholder} = this.props.dataReducer;
        if (!dataPlaceholder) return;
        const keys = Object.keys(dataPlaceholder);
        const idx = keys.indexOf(currentId);
        if (idx !== -1 && idx < keys.length - 1) {
            this.setActiveSection(keys[idx + 1]);
        }
    };

    jumpToNextUnfilled = () => {
        const {dataPlaceholder} = this.props.dataReducer;
        if (!dataPlaceholder) return;

        const filledSections = this.getFilledSections();
        const nextKey = Object.keys(dataPlaceholder).find(key => !filledSections[key]);
        if (!nextKey) return;

        this.setActiveSection(nextKey);
        const anchor = document.getElementById(nextKey);
        if (anchor) anchor.scrollIntoView({behavior: 'smooth', block: 'start'});
    };

    toggleFilledOnly = () => {
        this.setState(prevState => ({showFilledOnly: !prevState.showFilledOnly}));
    };

    collapseAll = () => {
        this.setState(prev => ({ globalCollapseKey: prev.globalCollapseKey + 1 }));
    };

    expandAll = () => {
        const { dataPlaceholder } = this.props.dataReducer;
        if (!dataPlaceholder) return;
        this.setState(prev => {
            const newKeys = {};
            Object.keys(dataPlaceholder).forEach(key => {
                newKeys[key] = (prev.sectionExpandKeys[key] || 0) + 1;
            });
            return { sectionExpandKeys: newKeys };
        });
    };

    getFilledSections = () => {
        const {dataPlaceholder} = this.props.dataReducer;
        const {patientReport} = this.state;
        const filledSections = {};

        if (!dataPlaceholder) return filledSections;

        Object.keys(dataPlaceholder).forEach(key => {
            filledSections[key] = reportUtils.hasReportData(patientReport[key]);
        });

        return filledSections;
    };

    renderSection = (key, filledSections) => {
        const {dataPlaceholder} = this.props.dataReducer;
        const {patientInfo, patientReport, showFilledOnly, sectionExpandKeys} = this.state;
        const sectionIsFilled = filledSections[key];

        if (showFilledOnly && !sectionIsFilled) return null;

        const commonProps = {
            key,
            id: key,
            onPatientReportChanged: this.onPatientReportChanged,
            onClear: this.onClearSection,
            onAdvanceSection: this.advanceToNextSection,
            preview: false,
            isFilled: sectionIsFilled,
            patientReport: patientReport[key],
            placeholder: dataPlaceholder[key],
            extras: {gender: patientInfo.gender || ''},
            expandKey: sectionExpandKeys[key] || 0,
            collapseKey: this.state.globalCollapseKey,
            showAbnormalBadges: !this.state.settings.hideHighLowChips,
            boldAbnormal: this.state.settings.boldAbnormal,
        };

        if (key === 'WIDAL') return <WidalSection {...commonProps}/>;
        return <Section {...commonProps}/>;
    };

    render() {
        const {loading, dataPlaceholder, error} = this.props.dataReducer;
        const {
            patientInfo, activeSection, showFilledOnly, validationMessages,
            recoverableDraft, lastDraftSavedAt, loadError, sectionSearch, attemptedPreview, undoToast,
            showLoadModal, cloudSaveStatus, cloudDocId, sidebarOpen,
        } = this.state;
        const filledSections = this.getFilledSections();
        const filledCount = Object.values(filledSections).filter(Boolean).length;

        const filteredKeys = dataPlaceholder
            ? Object.keys(dataPlaceholder).filter(key =>
                !sectionSearch || dataPlaceholder[key].name.toLowerCase().includes(sectionSearch.toLowerCase())
            )
            : [];

        if (error) {
            return <div><h1 className='error'>There is an error loading the report catalog.</h1></div>;
        }

        return (
            <div className="app-shell">
                <nav id="side_nav_bar" className="navbar sticky-top navbar-dark bg-dark app-toolbar">
                    <div className="brand-lockup">
                        <button className="btn btn-outline-light burger-btn" onClick={this.toggleSidebar}
                                data-tooltip={sidebarOpen ? 'Hide sidebar' : 'Show sidebar'}
                                aria-label={sidebarOpen ? 'Hide sidebar' : 'Show sidebar'}>☰</button>
                        <h2 className='text-light m-2 align-self-center'>
                            <img id='jagdamba-logo'
                                 className='align-self-center'
                                 src={process.env.PUBLIC_URL + '/microscope@192x192.png'}
                                 alt=''/>JAGDAMBA LAB</h2>
                        <span className="draft-status">
                            {lastDraftSavedAt ? `Draft saved ${lastDraftSavedAt}` : 'Local draft ready'}
                        </span>
                    </div>

                    <div className="toolbar-actions">
                        {cloudSaveStatus === 'saving' &&
                            <span className="cloud-save-status cloud-save-saving">☁ Saving…</span>}
                        {cloudSaveStatus === 'saved' &&
                            <span className="cloud-save-status cloud-save-ok">☁ Saved</span>}
                        {cloudSaveStatus === 'error' &&
                            <span className="cloud-save-status cloud-save-error">☁ Cloud save failed</span>}

                        <button type="button" className="btn btn-outline-light m-1"
                                data-tooltip="Settings" aria-label="Settings"
                                onClick={this.handleOpenSettings}>⚙</button>


                        <button type="button" className="btn btn-primary m-1"
                                onClick={this.handleOpenLoadModal}>Load
                        </button>

                        <button type="button"
                                onClick={this.handlePrint}
                                disabled={this.state.isPrinting}
                                className="btn btn-info m-1">
                            {this.state.isPrinting ? 'Generating…' : 'Print'}
                        </button>

                        <button type="button"
                                className="btn btn-outline-danger m-1"
                                onClick={this.handleDeleteFromCloud}
                                disabled={!cloudDocId}
                                title={cloudDocId ? 'Delete this report from the cloud' : 'Load a report from the cloud to enable delete'}>
                            Delete
                        </button>

                        <button type="button" onClick={this.clearAll}
                                className="btn btn-outline-danger m-1">Clear
                        </button>
                    </div>

                    {recoverableDraft &&
                    <div className="draft-banner">
                        <span>A saved local draft is available.</span>
                        <button className="btn btn-sm btn-success" onClick={this.restoreDraft}>Restore</button>
                        <button className="btn btn-sm btn-outline-secondary" onClick={this.dismissDraft}>Dismiss</button>
                    </div>}

                    {loadError &&
                    <div className="alert alert-danger app-alert nav-alert">{loadError}</div>}

                    {validationMessages.length > 0 &&
                    <div className="alert alert-warning app-alert nav-alert">
                        <strong>Cannot print: </strong>
                        {validationMessages.join(' · ')}
                    </div>}

                    {loading &&
                    <div className="app-alert alert alert-info nav-alert">Loading report catalog...</div>}
                </nav>

                <div id="wrapper" className={sidebarOpen ? 'toggled' : ''}>
                    {dataPlaceholder && <div id="sidebar-wrapper">
                        <div className="section-filter">
                            <button className={`btn btn-sm ${showFilledOnly ? 'btn-warning' : 'btn-outline-light'}`}
                                    onClick={this.toggleFilledOnly}>
                                {showFilledOnly ? 'Showing filled' : 'Show filled only'}
                            </button>
                            <span>{filledCount} filled</span>
                            <button className="btn btn-sm btn-outline-light"
                                    data-tooltip="Expand all" aria-label="Expand all sections"
                                    onClick={this.expandAll}>⊞</button>
                            <button className="btn btn-sm btn-outline-light"
                                    data-tooltip="Collapse all" aria-label="Collapse all sections"
                                    onClick={this.collapseAll}>⊟</button>
                        </div>
                        <div className="section-search">
                            <input
                                type="text"
                                placeholder="Search sections..."
                                value={sectionSearch}
                                onChange={e => this.setState({sectionSearch: e.target.value})}
                            />
                        </div>
                        <ul className="sidebar-nav">
                            <li>
                                <a className={activeSection === 'PATIENT_INFO' ? 'active-sidebar-link' : ''}
                                   onClick={() => this.setActiveSection('PATIENT_INFO')}
                                   href="#PATIENT_INFO">PATIENT INFORMATION</a>
                            </li>
                            {filteredKeys.map(key => {
                                const active = activeSection === key;
                                const filled = filledSections[key];
                                if (showFilledOnly && !filled) return null;
                                return <li key={key}>
                                    <a className={`${filled ? 'override-sidebar-nav-li-a' : ''} ${active ? 'active-sidebar-link' : ''}`}
                                       onClick={() => this.setActiveSection(key)}
                                       href={`#${key}`}>
                                        <span className="sidebar-section-name">{shortenSectionName(dataPlaceholder[key]['name'])}</span>
                                        {filled && <span className="section-dot">Filled</span>}
                                    </a>
                                </li>
                            })}
                        </ul>
                    </div>}

                    <div id="page-content-wrapper">
                        {dataPlaceholder && <div className='container-fluid'>
                            <PatientInfo id='PATIENT_INFO'
                                         onPatientInfoChanged={this.onPatientInfoChanged}
                                         preview={false}
                                         patientInfo={patientInfo}
                                         attemptedPreview={attemptedPreview}
                            />
                            <div className="workflow-summary">
                                <span>{Object.keys(dataPlaceholder).length} available report sections</span>
                                <span>{filledCount} filled</span>
                                <span>{showFilledOnly ? 'Filtered to filled sections' : 'Showing all sections'}</span>
                            </div>
                            {filteredKeys.map(key => this.renderSection(key, filledSections))}
                        </div>}
                    </div>
                </div>

                {undoToast &&
                <div className="undo-toast">
                    <span>{undoToast.message}</span>
                    <button className="btn btn-sm btn-warning" onClick={this.applyUndo}>Undo</button>
                    <button className="btn btn-sm btn-outline-light" onClick={this.dismissUndoToast}>Dismiss</button>
                </div>}

                {showLoadModal &&
                <LoadModal
                    onClose={this.handleCloseLoadModal}
                    onLoadFromFile={() => { this.handleCloseLoadModal(); this.handleLoadFromPC(); }}
                    onSelectRecord={this.handleSelectCloudRecord}
                />}

                {this.state.showSettingsModal &&
                <SettingsModal onClose={this.handleCloseSettings} />}
            </div>
        );
    }
}

const mapState = (state) => {
    return {
        dataReducer: state.dataReducer,
    };
};

const actionCreators = {
    getDataPlaceholder: dataActions.getDataPlaceholder,
};

export default connect(mapState, actionCreators)(Home);
