import React, {Component} from 'react';

class TextAreaX extends Component {
    constructor(props) {
        super(props);

        this.ref = React.createRef();
        let allSuggestion = localStorage.getItem('suggestions');

        if (allSuggestion) {
            try {
                allSuggestion = JSON.parse(allSuggestion);
            } catch (e) {
                allSuggestion = {};
            }
        } else {
            allSuggestion = {};
        }

        this.state = {
            focused: false,
            suggestions: allSuggestion[this.props.name] ? allSuggestion[this.props.name] : [],
        };
    }

    componentDidMount() {
        this.resizeTextarea();
    }

    componentDidUpdate() {
        this.resizeTextarea();
    }

    resizeTextarea = () => {
        if (!this.ref.current) {
            return;
        }

        this.ref.current.style.height = "0px";
        this.ref.current.style.height = this.ref.current.scrollHeight + "px";
    };

    onChange = (e) => {
        this.props.onChange(e.target.value);
    };

    onFocus = () => {
        this.setState({focused: true});
    };

    onItemClicked = (value) => {
        this.setState({focused: false});
        this.props.onChange(value);
    };

    onBlur = () => {
        const value = this.props.value;
        const numHistory = this.props.numHistory;

        if (value && !this.state.suggestions.includes(value)) {
            const suggestions = [value].concat(this.state.suggestions).slice(0, numHistory);
            this.setState({focused: false, suggestions});
            this.storeSuggestions(suggestions);
            return;
        }

        this.setState({focused: false});
    };

    storeSuggestions = (suggestions) => {
        const {name} = this.props;
        let allSuggestions = localStorage.getItem("suggestions");

        if (allSuggestions) {
            try {
                allSuggestions = JSON.parse(allSuggestions);
            } catch (e) {
                allSuggestions = {};
            }
            allSuggestions = {...allSuggestions, [name]: suggestions}
        } else {
            allSuggestions = {[name]: suggestions}
        }

        localStorage.setItem("suggestions", JSON.stringify(allSuggestions));
    };

    clearHistory = (e, i) => {
        e.stopPropagation();
        const suggestions = this.state.suggestions.filter((suggestion, index) => index !== i);
        this.setState({suggestions});
        this.storeSuggestions(suggestions);
    };

    render() {
        const {focused, suggestions} = this.state;
        const {className, name, showSuggestion} = this.props;
        const value = this.props.value || '';

        const filteredSuggestion = suggestions.filter(
            suggestion => !value || suggestion.toLowerCase().includes(value.toLowerCase())
        );

        return (
            <div className='dropdown'>
                <textarea
                    className={className}
                    name={name}
                    value={value}
                    ref={this.ref}
                    onChange={this.onChange}
                    onFocus={this.onFocus}
                    onBlur={filteredSuggestion.length === 0 ? this.onBlur : null}
                    rows='1'
                />

                {showSuggestion && focused && filteredSuggestion.length > 0 &&
                <OutsideAlerter onOutsideClick={this.onBlur}>
                    <div className='dropdown-menu show suggestion-menu'>
                        {filteredSuggestion.map((suggestion, i) => {
                            return <button key={suggestion} onClick={() => {
                                this.onItemClicked(suggestion);
                            }} className="dropdown-item show suggestion-item" type="button">
                                <span>{suggestion}</span>
                                <span
                                    className='suggestion-remove'
                                    onClick={(e) => {
                                        this.clearHistory(e, i);
                                    }}>x
                                </span>
                            </button>
                        })}
                    </div>
                </OutsideAlerter>}
            </div>
        );
    }
}

class OutsideAlerter extends Component {
    constructor(props) {
        super(props);

        this.setWrapperRef = this.setWrapperRef.bind(this);
        this.handleClickOutside = this.handleClickOutside.bind(this);
    }

    componentDidMount() {
        document.addEventListener('mousedown', this.handleClickOutside);
    }

    componentWillUnmount() {
        document.removeEventListener('mousedown', this.handleClickOutside);
    }

    setWrapperRef(node) {
        this.wrapperRef = node;
    }

    handleClickOutside(event) {
        if (this.wrapperRef && !this.wrapperRef.contains(event.target)) {
            if (this.props.onOutsideClick) {
                this.props.onOutsideClick();
            }
        }
    }

    render() {
        return <div ref={this.setWrapperRef}>{this.props.children}</div>;
    }
}

export default TextAreaX;
