import React, { Component } from 'react';
import { fetchReports, searchReports } from '../services/cloudStorage';

const PAGE_SIZE = 50;

const COLUMNS = [
    { key: 'patientNameDisplay', label: 'Patient',  sortKey: 'patientName' },
    { key: 'age',                label: 'Age',       sortKey: 'age',       numeric: true },
    { key: 'sex',                label: 'Sex',       sortKey: 'sex' },
    { key: 'date',               label: 'Date',      sortKey: 'date' },
    { key: 'savedAt',            label: 'Saved',     sortKey: 'savedAt' },
];

function sortRecords(records, field, dir) {
    return [...records].sort((a, b) => {
        let av = a[field] != null ? a[field] : '';
        let bv = b[field] != null ? b[field] : '';
        if (field === 'age') {
            av = parseFloat(av) || 0;
            bv = parseFloat(bv) || 0;
            return dir === 'asc' ? av - bv : bv - av;
        }
        av = String(av).toLowerCase();
        bv = String(bv).toLowerCase();
        if (av < bv) return dir === 'asc' ? -1 : 1;
        if (av > bv) return dir === 'asc' ? 1 : -1;
        return 0;
    });
}

class LoadModal extends Component {
    constructor(props) {
        super(props);
        this.state = {
            records: [],
            loading: true,
            error: '',
            query: '',
            sortField: 'savedAt',
            sortDir: 'desc',
            visibleCount: PAGE_SIZE,
        };
        this.searchRef  = React.createRef();
        this.bodyRef    = React.createRef();
    }

    componentDidMount() {
        fetchReports()
            .then(records => {
                this.setState({ records, loading: false });
                setTimeout(() => this.searchRef.current && this.searchRef.current.focus(), 50);
            })
            .catch(() => this.setState({ loading: false, error: 'Could not reach the cloud. Check your connection.' }));
    }

    handleKeyDown = (e) => {
        if (e.key === 'Escape') this.props.onClose();
    };

    handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) this.props.onClose();
    };

    handleQueryChange = (e) => {
        this.setState({ query: e.target.value, visibleCount: PAGE_SIZE });
    };

    handleSort = (col) => {
        const { sortField, sortDir } = this.state;
        if (sortField === col.sortKey) {
            this.setState({ sortDir: sortDir === 'asc' ? 'desc' : 'asc', visibleCount: PAGE_SIZE });
        } else {
            // Default direction: savedAt → desc, everything else → asc
            this.setState({ sortField: col.sortKey, sortDir: col.sortKey === 'savedAt' ? 'desc' : 'asc', visibleCount: PAGE_SIZE });
        }
    };

    handleScroll = () => {
        const el = this.bodyRef.current;
        if (!el) return;
        if (el.scrollTop + el.clientHeight >= el.scrollHeight - 80) {
            this.setState(prev => ({ visibleCount: prev.visibleCount + PAGE_SIZE }));
        }
    };

    sortIcon(col) {
        const { sortField, sortDir } = this.state;
        if (sortField !== col.sortKey) return <span className="sort-icon sort-icon-idle">⇅</span>;
        return <span className="sort-icon sort-icon-active">{sortDir === 'asc' ? '▲' : '▼'}</span>;
    }

    formatSavedAt = (iso) => {
        if (!iso) return '';
        try {
            return new Date(iso).toLocaleString('en-US', {
                year: 'numeric', month: 'short', day: 'numeric',
                hour: '2-digit', minute: '2-digit',
            });
        } catch { return iso; }
    };

    cellValue(col, record) {
        if (col.key === 'savedAt') return this.formatSavedAt(record.savedAt);
        return record[col.key] || '—';
    }

    render() {
        const { onClose, onLoadFromFile, onSelectRecord } = this.props;
        const { records, loading, error, query, sortField, sortDir, visibleCount } = this.state;

        const filtered = searchReports(records, query);
        const sorted   = sortRecords(filtered, sortField, sortDir);
        const visible  = sorted.slice(0, visibleCount);
        const hasMore  = visible.length < sorted.length;

        return (
            <div className="load-modal-backdrop" onClick={this.handleBackdropClick} onKeyDown={this.handleKeyDown}>
                <div className="load-modal" role="dialog" aria-modal="true" aria-label="Load report">

                    <div className="load-modal-header">
                        <h5 className="load-modal-title">Load Report</h5>
                        <button className="load-modal-close" onClick={onClose}
                                data-tooltip="Close" aria-label="Close">✕</button>
                    </div>

                    <div className="load-modal-search">
                        <input
                            ref={this.searchRef}
                            type="text"
                            className="load-modal-search-input"
                            placeholder='Search — "john" · "john july" · "john 25" (name · month · age)'
                            value={query}
                            onChange={this.handleQueryChange}
                        />
                    </div>

                    <div className="load-modal-body" ref={this.bodyRef} onScroll={this.handleScroll}>
                        {loading && <div className="load-modal-status">Loading records…</div>}
                        {!loading && error && <div className="load-modal-status load-modal-error">{error}</div>}
                        {!loading && !error && filtered.length === 0 && (
                            <div className="load-modal-status">No records match your search.</div>
                        )}
                        {!loading && !error && filtered.length > 0 && (
                            <table className="load-modal-table">
                                <thead>
                                    <tr>
                                        {COLUMNS.map(col => (
                                            <th key={col.key}
                                                className="load-modal-th"
                                                onClick={() => this.handleSort(col)}>
                                                {col.label}{this.sortIcon(col)}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody>
                                    {visible.map(record => (
                                        <tr key={record.id}
                                            className="load-modal-row"
                                            onClick={() => onSelectRecord(record)}
                                            title="Click to load this report">
                                            {COLUMNS.map(col => (
                                                <td key={col.key}
                                                    className={col.key === 'savedAt' ? 'load-modal-saved-at' : ''}>
                                                    {this.cellValue(col, record)}
                                                </td>
                                            ))}
                                        </tr>
                                    ))}
                                    {hasMore && (
                                        <tr>
                                            <td colSpan={COLUMNS.length} className="load-modal-load-more">
                                                Scroll for more — showing {visible.length} of {sorted.length}
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        )}
                    </div>

                    <div className="load-modal-footer">
                        <span className="load-modal-count">
                            {!loading && !error && `${sorted.length} of ${records.length} records`}
                        </span>
                        <button className="btn btn-sm btn-outline-secondary" onClick={onLoadFromFile}>
                            Load from file instead
                        </button>
                    </div>

                </div>
            </div>
        );
    }
}

export default LoadModal;
