import React, { useState, useEffect } from 'react';
import { loadSettings, saveSettings, SETTINGS_DEFAULTS } from '../helper/settingsUtils';
import { signOut } from 'firebase/auth';
import { auth } from '../services/firebase';

function SettingsModal({ onClose }) {
    const [s, setS] = useState(loadSettings);
    // Raw string drafts for number inputs while the user is typing.
    // Keyed by a unique string per input. Cleared on blur after clamping.
    const [draft, setDraft] = useState({});

    useEffect(() => {
        const handler = (e) => { if (e.key === 'Escape') onClose(); };
        document.addEventListener('keydown', handler);
        return () => document.removeEventListener('keydown', handler);
    }, [onClose]);

    // ── helpers ────────────────────────────────────────────────────────────

    const update = (changes) => {
        const next = { ...s, ...changes };
        setS(next);
        saveSettings(next);
    };

    const resetToDefaults = () => {
        const defaults = {
            ...SETTINGS_DEFAULTS,
            pdfMargin: { ...SETTINGS_DEFAULTS.pdfMargin },
            tableCellPadding: { ...SETTINGS_DEFAULTS.tableCellPadding },
            fontSizes: { ...SETTINGS_DEFAULTS.fontSizes },
        };
        setS(defaults);
        setDraft({});
        saveSettings(defaults);
    };

    // While typing: just store the raw string, never clamp
    const numChange = (key, raw) => setDraft(d => ({ ...d, [key]: raw }));

    // On blur: parse, clamp, save to settings, clear draft
    const numBlur = (key, raw, min, max, saveFn) => {
        setDraft(d => { const n = { ...d }; delete n[key]; return n; });
        saveFn(clamp(raw, min, max));
    };

    // Current display value for a number input:
    // shows the draft (free-form string) while typing, actual value otherwise
    const numVal = (key, actual) =>
        draft[key] !== undefined ? draft[key] : actual;

    // Specific save helpers (called on blur)
    const saveMargin = (side, v) =>
        update({ pdfMargin: { ...s.pdfMargin, [side]: v } });

    const saveCellPad = (side, v) =>
        update({ tableCellPadding: { ...s.tableCellPadding, [side]: v } });

    const saveFontSize = (key, v) =>
        update({ fontSizes: { ...s.fontSizes, [key]: v } });

    // ── render ─────────────────────────────────────────────────────────────

    return (
        <div className="settings-backdrop" onClick={onClose}>
            <div className="settings-modal" onClick={e => e.stopPropagation()}>

                <div className="settings-modal-header">
                    <span className="settings-modal-title">Settings</span>
                    <button className="settings-modal-close" onClick={onClose}
                            data-tooltip="Close" aria-label="Close">✕</button>
                </div>

                <div className="settings-modal-body">

                    {/* ── DISPLAY ── */}
                    <section className="settings-section">
                        <h3 className="settings-section-title">Display</h3>

                        <label className="settings-toggle-row">
                            <div>
                                <div className="settings-label">Show High / Low Label</div>
                                <div className="settings-desc">Shows an H / L chip next to out-of-range values</div>
                            </div>
                            <input type="checkbox" className="settings-checkbox"
                                checked={!s.hideHighLowChips}
                                onChange={e => update({ hideHighLowChips: !e.target.checked })} />
                        </label>

                        <label className="settings-toggle-row settings-row-divider">
                            <div>
                                <div className="settings-label">Bold Abnormal Values</div>
                                <div className="settings-desc">Makes out-of-range results bold and coloured</div>
                            </div>
                            <input type="checkbox" className="settings-checkbox"
                                checked={s.boldAbnormal}
                                onChange={e => update({ boldAbnormal: e.target.checked })} />
                        </label>
                    </section>

                    {/* ── STORAGE ── */}
                    <section className="settings-section">
                        <h3 className="settings-section-title">Storage</h3>

                        <label className="settings-toggle-row">
                            <div>
                                <div className="settings-label">Auto-Save to Cloud</div>
                                <div className="settings-desc">Saves the report to the cloud on every print. Required for QR code.</div>
                            </div>
                            <input type="checkbox" className="settings-checkbox"
                                checked={s.saveToCloud}
                                onChange={e => {
                                    const checked = e.target.checked;
                                    update({ saveToCloud: checked, ...(!checked && { showQrInPdf: false }) });
                                }} />
                        </label>
                    </section>

                    {/* ── PDF ── */}
                    <section className="settings-section">
                        <h3 className="settings-section-title">PDF</h3>

                        <label className="settings-toggle-row">
                            <div>
                                <div className="settings-label">Show QR Code</div>
                                <div className="settings-desc">Adds a scannable QR at the bottom of the PDF.</div>
                            </div>
                            <input type="checkbox" className="settings-checkbox"
                                checked={s.showQrInPdf}
                                disabled={!s.saveToCloud}
                                onChange={e => update({ showQrInPdf: e.target.checked })} />
                        </label>

                        <div className="settings-row-divider">
                            <div className="settings-label" style={{ marginBottom: 8 }}>Page Margins (mm)</div>
                            <div className="settings-margin-grid">
                                {['top', 'right', 'bottom', 'left'].map(side => {
                                    const k = `m_${side}`;
                                    return (
                                        <label key={side} className="settings-margin-field">
                                            <span className="settings-margin-label">{cap(side)}</span>
                                            <input type="number" min="0" max="50" className="settings-number"
                                                value={numVal(k, s.pdfMargin[side])}
                                                onChange={e => numChange(k, e.target.value)}
                                                onBlur={e => numBlur(k, e.target.value, 0, 50, v => saveMargin(side, v))} />
                                        </label>
                                    );
                                })}
                            </div>
                        </div>

                        <div className="settings-field settings-row-divider">
                            <div className="settings-label" style={{ marginBottom: 4 }}>Signatures (PDF Footer)</div>
                            <div className="settings-desc" style={{ marginBottom: 10 }}>
                                Left and right signature blocks shown at the bottom of the PDF.
                                Each line is printed below the signature rule.
                            </div>
                            <div style={{ display: 'flex', gap: 12 }}>
                                <div style={{ flex: 1 }}>
                                    <label style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6, cursor: 'pointer' }}>
                                        <input type="checkbox" className="settings-checkbox"
                                            checked={s.showSignatureLeft !== false}
                                            onChange={e => update({ showSignatureLeft: e.target.checked })} />
                                        <span className="settings-margin-label">Left (show)</span>
                                    </label>
                                    <textarea className="settings-text" rows={5}
                                        style={{ resize: 'vertical', fontFamily: 'inherit' }}
                                        placeholder={"Name\nTitle\nNHPC No: xxx"}
                                        value={s.signatureLeft || ''}
                                        onChange={e => update({ signatureLeft: e.target.value })} />
                                </div>
                                <div style={{ flex: 1 }}>
                                    <label style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6, cursor: 'pointer' }}>
                                        <input type="checkbox" className="settings-checkbox"
                                            checked={s.showSignatureRight !== false}
                                            onChange={e => update({ showSignatureRight: e.target.checked })} />
                                        <span className="settings-margin-label">Right (show)</span>
                                    </label>
                                    <textarea className="settings-text" rows={5}
                                        style={{ resize: 'vertical', fontFamily: 'inherit' }}
                                        placeholder={"Name\nTitle\nNHPC No: xxx"}
                                        value={s.signatureRight || ''}
                                        onChange={e => update({ signatureRight: e.target.value })} />
                                </div>
                            </div>
                        </div>
                    </section>

                    {/* ── TABLE ── */}
                    <section className="settings-section">
                        <h3 className="settings-section-title">Table (PDF)</h3>

                        <div className="settings-field">
                            <div className="settings-label">Cell Padding (pt)</div>
                            <div className="settings-desc" style={{ marginBottom: 8 }}>Inner padding of each table cell</div>
                            <div className="settings-margin-grid">
                                {[
                                    { side: 'vertical',   label: 'Vertical',   max: 10 },
                                    { side: 'horizontal', label: 'Horizontal', max: 10 },
                                ].map(({ side, label, max }) => {
                                    const k = `cp_${side}`;
                                    return (
                                        <label key={side} className="settings-margin-field">
                                            <span className="settings-margin-label">{label}</span>
                                            <input type="number" min="0" max={max} className="settings-number"
                                                value={numVal(k, s.tableCellPadding[side])}
                                                onChange={e => numChange(k, e.target.value)}
                                                onBlur={e => numBlur(k, e.target.value, 0, max, v => saveCellPad(side, v))} />
                                        </label>
                                    );
                                })}
                            </div>
                        </div>

                        <div className="settings-field settings-row-divider">
                            <div className="settings-label">Space Between Tables (pt)</div>
                            <div className="settings-desc" style={{ marginBottom: 8 }}>Gap between each test section</div>
                            <input type="number" min="0" max="40" className="settings-number"
                                value={numVal('ts', s.tableSpacing)}
                                onChange={e => numChange('ts', e.target.value)}
                                onBlur={e => numBlur('ts', e.target.value, 0, 40, v => update({ tableSpacing: v }))} />
                        </div>
                    </section>

                    {/* ── FONT SIZES ── */}
                    <section className="settings-section">
                        <h3 className="settings-section-title">Font Sizes (PDF)</h3>

                        <div className="settings-margin-grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
                            {[
                                { key: 'body',           label: 'Body text'       },
                                { key: 'sectionHeading', label: 'Section heading' },
                                { key: 'labName',        label: 'Lab name'        },
                                { key: 'endOfReport',    label: 'End of report'   },
                                { key: 'qrLabel',        label: 'QR caption'      },
                            ].map(({ key, label }) => {
                                const k = `fs_${key}`;
                                const actual = (s.fontSizes || {})[key] ?? SETTINGS_DEFAULTS.fontSizes[key];
                                return (
                                    <label key={key} className="settings-margin-field">
                                        <span className="settings-margin-label">{label}</span>
                                        <input type="number" min="5" max="30" className="settings-number"
                                            value={numVal(k, actual)}
                                            onChange={e => numChange(k, e.target.value)}
                                            onBlur={e => numBlur(k, e.target.value, 5, 30, v => saveFontSize(key, v))} />
                                    </label>
                                );
                            })}
                        </div>
                    </section>

                    {/* ── ACCOUNT ── */}
                    <section className="settings-section">
                        <h3 className="settings-section-title">Account</h3>
                        <div style={{ display: 'flex', gap: 10 }}>
                            <button className="btn btn-sm btn-outline-secondary" onClick={resetToDefaults}
                                    title="Reset all settings to defaults">Reset to defaults</button>
                            <button className="btn btn-sm btn-outline-danger"
                                    onClick={() => { onClose(); signOut(auth); }}>
                                Sign out
                            </button>
                        </div>
                    </section>

                </div>
            </div>
        </div>
    );
}

function clamp(val, min, max) {
    const n = Number(val);
    if (isNaN(n) || val === '') return min;
    return Math.max(min, Math.min(max, n));
}

function cap(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
}

export default SettingsModal;
