import React from 'react';
import { Document, Page, View, Text, StyleSheet, Image } from '@react-pdf/renderer';
import { reportUtils } from '../helper/reportUtils';
import { SETTINGS_DEFAULTS } from '../helper/settingsUtils';

const BORDER = '#444';
const SUBGROUP_BORDER = '#bbb';
const HEADER_BG = '#f0f0f0';
const BOLD = 'Helvetica-Bold';
const NORMAL = 'Helvetica';
const CHIP_HIGH = '#b42318';
const CHIP_LOW  = '#1d4ed8';

const mmToPt = mm => mm * 2.835;

const styles = StyleSheet.create({
    page: {
        fontFamily: NORMAL,
        fontSize: 8,
        color: '#000',
    },

    labHeader: {
        textAlign: 'center',
        marginBottom: 10,
    },
    labName: {
        fontFamily: BOLD,
        fontSize: 13,
        letterSpacing: 1,
    },

    section: {
        marginBottom: 8,
    },
    sectionHeading: {
        fontFamily: BOLD,
        fontSize: 9,
        marginBottom: 2,
    },

    table: {
        borderWidth: 1,
        borderColor: BORDER,
        borderStyle: 'solid',
    },

    row: { flexDirection: 'row' },
    headerRow: {
        flexDirection: 'row',
        backgroundColor: HEADER_BG,
        borderBottomWidth: 1,
        borderBottomColor: BORDER,
        borderBottomStyle: 'solid',
    },
    subHeaderRow: {
        flexDirection: 'row',
        borderBottomWidth: 0.5,
        borderBottomColor: SUBGROUP_BORDER,
        borderBottomStyle: 'solid',
    },

    cell: {
        paddingVertical: 2,
        paddingHorizontal: 4,
        flexShrink: 0,
        flexWrap: 'wrap',
    },
    headerCell: {
        fontFamily: BOLD,
        paddingVertical: 2,
        paddingHorizontal: 4,
        flexShrink: 0,
    },
    abnormal: { fontFamily: BOLD },

    chipText: {
        fontFamily: BOLD,
        fontSize: 6,
    },

    // Patient info table
    piTable: {
        borderWidth: 1,
        borderColor: BORDER,
        borderStyle: 'solid',
    },
    piRow: {
        flexDirection: 'row',
        borderBottomWidth: 0.5,
        borderBottomColor: SUBGROUP_BORDER,
        borderBottomStyle: 'solid',
    },
    piLastRow: { flexDirection: 'row' },
    piLabel: { fontFamily: BOLD, paddingVertical: 3, paddingHorizontal: 4 },
    piValue: { paddingVertical: 3, paddingHorizontal: 4 },

    // End of report
    endOfReport: {
        textAlign: 'center',
        fontSize: 8,
        fontFamily: BOLD,
        marginTop: 12,
        marginBottom: 4,
        color: '#374151',
    },

    // Footer
    footer: {
        marginTop: 12,
        paddingTop: 6,
    },
    sigRow: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'flex-end',
    },
    sigBlock: {
        width: '38%',
    },
    sigRule: {
        borderTopWidth: 1,
        borderTopColor: '#000',
        borderTopStyle: 'solid',
        marginBottom: 4,
        width: '60%',
    },
    sigLine: {
        fontSize: 8,
        color: '#1f2937',
    },
    qrImage: {
        height: 72,
        width: 72,
    },
    qrLabel: {
        fontSize: 7,
        color: '#6b7280',
        marginTop: 3,
        textAlign: 'center',
    },
    signature: {
        fontSize: 8,
        textAlign: 'center',
        marginBottom: 6,
        color: '#374151',
    },
});

// Column widths — Test Name 30%, always summing to 100%
const COL_WIDTHS = {
    4: { name: '30%', result: '20%', unit: '15%', range: '35%' },
    3: { name: '30%', result: '20%', unit: '50%' },
    2: { name: '30%', result: '70%' },
};

function formatRange(item) {
    if (item.type !== 'range' || !item.range) return '';
    const r = item.range;
    if (r.M && r.F) {
        if (r.M.lower && r.F.lower) return `M(${r.M.lower}-${r.M.higher}) F(${r.F.lower}-${r.F.higher})`;
        return `M(<${r.M.higher}) F(<${r.F.higher})`;
    }
    if (r.lower !== undefined) return `(${r.lower}-${r.higher})`;
    return `< ${r.higher}`;
}

function unitRangeForRows(dataRows, sectionReport) {
    let noUnit = true, noRange = true;
    for (const row of dataRows) {
        if (row.unit && reportUtils.isFilledValue(sectionReport[row.id])) noUnit = false;
        if (row.range && reportUtils.isFilledValue(sectionReport[row.id])) noRange = false;
    }
    return { noUnit, noRange };
}

function unitRangeForSection(placeholder, sectionReport) {
    if (placeholder.sub_category) {
        let noUnit = true, noRange = true;
        for (const sub of placeholder.sub_category) {
            const r = unitRangeForRows(sub.data, sectionReport);
            noUnit = noUnit && r.noUnit;
            noRange = noRange && r.noRange;
        }
        return { noUnit, noRange };
    }
    return unitRangeForRows(placeholder.data, sectionReport);
}

function PatientInfoSection({ patientInfo, tableSpacing }) {
    const {
        name = '', age = '', gender = '', address = '',
        labNumber = '', refDoctorName = '', date = '',
    } = patientInfo;
    const genderDisplay = gender && gender !== reportUtils.EMPTY_SELECT_VALUE ? gender : '';

    return (
        <View wrap={false} style={[styles.piTable, { marginBottom: tableSpacing != null ? tableSpacing : 8 }]}>
            <View style={styles.piRow}>
                <Text style={[styles.piLabel, { width: '20%' }]}>Patient Name:</Text>
                <Text style={[styles.piValue, { width: '39%' }]}>{name}</Text>
                <Text style={[styles.piLabel, { width: '10%' }]}>Age:</Text>
                <Text style={[styles.piValue, { width: '16%' }]}>{age}</Text>
                <Text style={[styles.piLabel, { width: '5%' }]}>Sex:</Text>
                <Text style={[styles.piValue, { width: '10%' }]}>{genderDisplay}</Text>
            </View>
            <View style={styles.piRow}>
                <Text style={[styles.piLabel, { width: '20%' }]}>Address:</Text>
                <Text style={[styles.piValue, { width: '39%' }]}>{address}</Text>
                <Text style={[styles.piLabel, { width: '10%' }]}>Lab No:</Text>
                <Text style={[styles.piValue, { width: '31%' }]}>{labNumber}</Text>
            </View>
            <View style={styles.piLastRow}>
                <Text style={[styles.piLabel, { width: '20%' }]}>Ref. by Dr:</Text>
                <Text style={[styles.piValue, { width: '39%' }]}>{refDoctorName}</Text>
                <Text style={[styles.piLabel, { width: '10%' }]}>Date:</Text>
                <Text style={[styles.piValue, { width: '31%' }]}>{date}</Text>
            </View>
        </View>
    );
}

function DataRow({ item, report, w, noUnit, noRange, gender, cellPad, boldAbnormal, showChips }) {
    const raw = report[item.id];
    if (!reportUtils.isFilledValue(raw)) return null;
    const value = raw === reportUtils.EMPTY_SELECT_VALUE ? '' : String(raw);
    if (!value) return null;

    const abnormalStatus = reportUtils.getAbnormalStatus(item, value, gender); // 'high' | 'low' | null
    const isAbnormal = !!abnormalStatus;
    const pad = { paddingVertical: cellPad.vertical, paddingHorizontal: cellPad.horizontal };
    const bold = boldAbnormal && isAbnormal ? styles.abnormal : null;
    const chipColor = abnormalStatus === 'high' ? CHIP_HIGH : CHIP_LOW;

    return (
        <View style={styles.row}>
            <Text style={[styles.cell, pad, { width: w.name }]}>{item.name}</Text>
            <View style={[pad, { width: w.result, flexShrink: 0, flexDirection: 'row', alignItems: 'center' }]}>
                <Text style={[bold, { flexGrow: 1 }]}>{value}</Text>
                {showChips && abnormalStatus ? (
                    <View style={{ borderWidth: 0.5, borderColor: chipColor, borderRadius: 2, marginLeft: 3, paddingHorizontal: 2, paddingVertical: 0.5 }}>
                        <Text style={[styles.chipText, { color: chipColor }]}>
                            {abnormalStatus === 'high' ? 'High' : 'Low'}
                        </Text>
                    </View>
                ) : <View />}
            </View>
            {!noUnit  && <Text style={[styles.cell, pad, { width: w.unit }]}>{item.unit || ''}</Text>}
            {!noRange && <Text style={[styles.cell, pad, { width: w.range }]}>{formatRange(item)}</Text>}
        </View>
    );
}

function SectionTable({ placeholder, sectionReport, gender, cellPad, tableSpacing, boldAbnormal, showChips, sectionHeadingFontSize }) {
    if (!reportUtils.hasReportData(sectionReport)) return null;

    const { noUnit, noRange } = unitRangeForSection(placeholder, sectionReport);
    const cols = 2 + (noUnit ? 0 : 1) + (noRange ? 0 : 1);
    const w = COL_WIDTHS[cols];
    const pad = { paddingVertical: cellPad.vertical, paddingHorizontal: cellPad.horizontal };

    return (
        <View wrap={false} style={[styles.section, { marginBottom: tableSpacing }]}>
            <Text style={[styles.sectionHeading, { fontSize: sectionHeadingFontSize }]}>{placeholder.name}</Text>
            <View style={styles.table}>
                <View style={styles.headerRow}>
                    <Text style={[styles.headerCell, pad, { width: w.name }]}>Test Name</Text>
                    <Text style={[styles.headerCell, pad, { width: w.result }]}>Result</Text>
                    {!noUnit  && <Text style={[styles.headerCell, pad, { width: w.unit }]}>Unit</Text>}
                    {!noRange && <Text style={[styles.headerCell, pad, { width: w.range }]}>Ref Range</Text>}
                </View>
                {placeholder.sub_category
                    ? placeholder.sub_category.map((sub, si) => {
                          const subHasData = sub.data.some(r => reportUtils.isFilledValue(sectionReport[r.id]));
                          if (!subHasData) return null;
                          return (
                              <View key={si}>
                                  <View style={styles.subHeaderRow}>
                                      <Text style={[styles.headerCell, pad, { width: '100%', paddingTop: Math.max(cellPad.vertical, 4) }]}>{sub.name}</Text>
                                  </View>
                                  {sub.data.map((item, ri) => (
                                      <DataRow key={ri} item={item} report={sectionReport} w={w}
                                               noUnit={noUnit} noRange={noRange} gender={gender}
                                               cellPad={cellPad} boldAbnormal={boldAbnormal} showChips={showChips} />
                                  ))}
                              </View>
                          );
                      })
                    : placeholder.data.map((item, ri) => (
                          <DataRow key={ri} item={item} report={sectionReport} w={w}
                                   noUnit={noUnit} noRange={noRange} gender={gender}
                                   cellPad={cellPad} boldAbnormal={boldAbnormal} showChips={showChips} />
                      ))
                }
            </View>
        </View>
    );
}

function WidalSection({ placeholder, sectionReport, cellPad, tableSpacing, sectionHeadingFontSize }) {
    if (!reportUtils.hasReportData(sectionReport)) return null;

    const { findings_column, data, name } = placeholder;
    const antigenW = '30%';
    const colW = `${Math.floor(70 / findings_column.length)}%`;
    const pad = { paddingVertical: cellPad.vertical, paddingHorizontal: cellPad.horizontal };

    return (
        <View wrap={false} style={[styles.section, { marginBottom: tableSpacing }]}>
            <Text style={[styles.sectionHeading, { fontSize: sectionHeadingFontSize }]}>{name}</Text>
            <View style={styles.table}>
                <View style={styles.headerRow}>
                    <Text style={[styles.headerCell, pad, { width: antigenW }]}>Antigen</Text>
                    {findings_column.map((col, i) => (
                        <Text key={i} style={[styles.headerCell, pad, { width: colW }]}>{col}</Text>
                    ))}
                </View>
                {data.map((row, ri) => {
                    const vals = sectionReport[row.id] || {};
                    const rowHasData = findings_column.some((_, i) => reportUtils.isFilledValue(vals[i]));
                    if (!rowHasData) return null;
                    return (
                        <View key={ri} style={styles.row}>
                            <Text style={[styles.cell, pad, { width: antigenW }]}>{row.name}</Text>
                            {findings_column.map((_, i) => {
                                const v = vals[i] || '';
                                return (
                                    <Text key={i} style={[styles.cell, pad, { width: colW }]}>
                                        {v === reportUtils.EMPTY_SELECT_VALUE ? '' : v}
                                    </Text>
                                );
                            })}
                        </View>
                    );
                })}
            </View>
        </View>
    );
}

function SignatureBlock({ text, bodyFontSize }) {
    const lines = (text || '').split('\n');
    const hasContent = lines.some(l => l.trim());
    if (!hasContent) return <View style={styles.sigBlock} />;
    return (
        <View style={styles.sigBlock}>
            <View style={styles.sigRule} />
            {lines.map((line, i) => (
                <Text key={i} style={[styles.sigLine, { fontSize: bodyFontSize }]}>{line}</Text>
            ))}
        </View>
    );
}

function ReportPDF({ patientInfo, patientReport, dataPlaceholder, qrDataUrl, settings, showLabHeader }) {
    const s = settings || SETTINGS_DEFAULTS;
    const gender = patientInfo.gender || '';
    const cellPad = s.tableCellPadding || SETTINGS_DEFAULTS.tableCellPadding;
    const tableSpacing = s.tableSpacing != null ? s.tableSpacing : SETTINGS_DEFAULTS.tableSpacing;
    const boldAbnormal = s.boldAbnormal !== false;
    const showChips = !s.hideHighLowChips;
    const fs = { ...SETTINGS_DEFAULTS.fontSizes, ...(s.fontSizes || {}) };

    const pageStyle = {
        paddingTop: mmToPt(s.pdfMargin.top),
        paddingBottom: mmToPt(s.pdfMargin.bottom),
        paddingLeft: mmToPt(s.pdfMargin.left),
        paddingRight: mmToPt(s.pdfMargin.right),
        fontSize: fs.body,
    };

    const hasLeft  = !!(s.signatureLeft  && s.signatureLeft.trim()  && s.showSignatureLeft  !== false);
    const hasRight = !!(s.signatureRight && s.signatureRight.trim() && s.showSignatureRight !== false);
    const hasSignatures = hasLeft || hasRight;
    const hasFooter = qrDataUrl || hasSignatures;

    return (
        <Document>
            <Page size="A4" style={[styles.page, pageStyle]}>
                <View style={{ flex: 1 }}>
                    {showLabHeader && (
                        <View style={styles.labHeader}>
                            <Text style={[styles.labName, { fontSize: fs.labName }]}>JAGDAMBA PATHOLOGY LAB</Text>
                        </View>
                    )}

                    <PatientInfoSection patientInfo={patientInfo} tableSpacing={tableSpacing} />

                    {Object.keys(dataPlaceholder).map(key => {
                        const placeholder = dataPlaceholder[key];
                        const raw = patientReport[key] || {};
                        const sectionReport = reportUtils.applyAutoFill(placeholder, raw);

                        if (key === 'WIDAL') {
                            return <WidalSection key={key} placeholder={placeholder}
                                                 sectionReport={sectionReport}
                                                 cellPad={cellPad} tableSpacing={tableSpacing}
                                                 sectionHeadingFontSize={fs.sectionHeading} />;
                        }
                        return (
                            <SectionTable key={key} placeholder={placeholder}
                                          sectionReport={sectionReport} gender={gender}
                                          cellPad={cellPad} tableSpacing={tableSpacing}
                                          boldAbnormal={boldAbnormal} showChips={showChips}
                                          sectionHeadingFontSize={fs.sectionHeading} />
                        );
                    })}

                    <Text style={[styles.endOfReport, { fontSize: fs.endOfReport }]}>** END OF REPORT **</Text>
                </View>

                {hasFooter ? (
                    <View wrap={false} style={styles.footer}>
                        {/* Row 1: left sig | QR image | right sig */}
                        <View style={styles.sigRow}>
                            {hasLeft ? (
                                <SignatureBlock text={s.signatureLeft} bodyFontSize={fs.body} />
                            ) : (
                                <View style={styles.sigBlock} />
                            )}

                            {qrDataUrl ? (
                                <Image src={qrDataUrl} style={styles.qrImage} />
                            ) : (
                                <View />
                            )}

                            {hasRight ? (
                                <SignatureBlock text={s.signatureRight} bodyFontSize={fs.body} />
                            ) : (
                                <View style={styles.sigBlock} />
                            )}
                        </View>

                        {/* Row 2: "Scan to view report" centred below the QR */}
                        {qrDataUrl ? (
                            <Text style={[styles.qrLabel, { fontSize: fs.qrLabel }]}>Scan to view report</Text>
                        ) : (
                            <View />
                        )}
                    </View>
                ) : (
                    <View />
                )}
            </Page>
        </Document>
    );
}

export default ReportPDF;
