import React, {Component} from 'react';
import TextAreaX from "./TextAreaX";
import NepaliDatePicker from "./NepaliDatePicker";

class PatientInfo extends Component {

    onChange = (e) => {
        const {name, value} = e.target;
        this.props.onPatientInfoChanged(name, value);
    };

    invalidClass = (value) => {
        const {preview, attemptedPreview} = this.props;
        return !preview && attemptedPreview && !value ? 'field-required-invalid' : '';
    };

    render() {
        const {name, age, gender, address, labNumber, refDoctorName, date} = this.props.patientInfo;
        const {preview, attemptedPreview} = this.props;

        return (
            <section className='patient-info-section no-page-break'>
                <span id={this.props.id} className='anchor'/>
                <div className="section-heading">
                    <h4>Patient Information</h4>
                </div>
                <table className='table table-bordered patient-info-table'>
                    <tbody>
                    <tr>
                        <td width="20%"><b>Patient Name:</b></td>
                        <td width="39%">
                            <TextAreaX
                                onChange={value => {
                                    this.props.onPatientInfoChanged('name', value);
                                }}
                                name='name'
                                preview={preview}
                                showSuggestion={false}
                                numHistory={5}
                                className={!preview && attemptedPreview && !name ? 'field-required-invalid' : ''}
                                value={name || ''}/>
                        </td>
                        <td width="10%"><b>Age:</b></td>
                        <td width="16%">
                            <input onChange={this.onChange}
                                   type='text'
                                   name='age'
                                   placeholder="e.g. 35y, 6m, 2y 6m"
                                   className={this.invalidClass(age)}
                                   value={age || ''}/>
                        </td>
                        <td width="5%"><b>Sex:</b></td>
                        <td width="10%">
                            {preview
                                ? <span>{gender && gender !== 'Not selected' ? gender : ''}</span>
                                : <div className={`option-group${!preview && attemptedPreview && (!gender || gender === 'Not selected') ? ' field-required-invalid' : ''}`}>
                                    <button type="button"
                                            className={`option-btn${gender === 'M' ? ' option-btn--selected' : ''}`}
                                            data-color-intent="male"
                                            onClick={() => this.props.onPatientInfoChanged('gender', gender === 'M' ? 'Not selected' : 'M')}>
                                        Male
                                    </button>
                                    <button type="button"
                                            className={`option-btn${gender === 'F' ? ' option-btn--selected' : ''}`}
                                            data-color-intent="female"
                                            onClick={() => this.props.onPatientInfoChanged('gender', gender === 'F' ? 'Not selected' : 'F')}>
                                        Female
                                    </button>
                                </div>
                            }
                        </td>
                    </tr>
                    <tr>
                        <td><b>Address:</b></td>
                        <td>
                            <input onChange={this.onChange} type='text' name='address'
                                   value={address || ''}/>
                        </td>
                        <td><b>Lab No:</b></td>
                        <td colSpan='3'>
                            <input onChange={this.onChange}
                                   type='text'
                                   name='labNumber'
                                   className={this.invalidClass(labNumber)}
                                   value={labNumber || ''}/>
                        </td>
                    </tr>
                    <tr>
                        <td><b>Ref. by Dr.</b></td>
                        <td>
                            <TextAreaX onChange={value => {
                                this.props.onPatientInfoChanged('refDoctorName', value);
                            }}
                                       name='refDoctorName'
                                       showSuggestion={true}
                                       numHistory={5}
                                       preview={preview}
                                       value={refDoctorName || ''}/>
                        </td>
                        <td><b>Date:</b></td>
                        <td colSpan='3'>
                            <NepaliDatePicker
                                value={date || ''}
                                preview={preview}
                                className={this.invalidClass(date)}
                                onChange={val => this.props.onPatientInfoChanged('date', val)}
                            />
                        </td>
                    </tr>
                    </tbody>
                </table>
            </section>
        );
    }
}

export default PatientInfo;
