import React, { useState, useEffect } from 'react';
import { Route } from 'react-router-dom';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from '../services/firebase';
import Home from './Home';
import ReportPreview from './ReportPreview';
import Login from './Login';

function App() {
    // undefined = still checking cached session, null = not logged in, object = logged in
    const [user, setUser] = useState(undefined);

    useEffect(() => {
        // Firebase restores the cached session automatically — this fires once on mount
        const unsubscribe = onAuthStateChanged(auth, u => setUser(u || null));
        return unsubscribe;
    }, []);

    // Checking cached auth state — show a minimal spinner so the screen doesn't flash
    if (user === undefined) {
        return (
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh' }}>
                <span style={{ color: '#888', fontSize: 14 }}>Loading…</span>
            </div>
        );
    }

    return (
        <div>
            {/* /report/:id is always public — needed for QR code scanning by patients/doctors */}
            <Route path="/report/:id" component={ReportPreview} />

            {/* Home requires login */}
            <Route exact path="/">
                {user ? <Home /> : <Login />}
            </Route>
        </div>
    );
}

export default App;
