import React, { useState } from 'react';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../services/firebase';

function Login() {
    const [email, setEmail]       = useState('');
    const [password, setPassword] = useState('');
    const [error, setError]       = useState('');
    const [loading, setLoading]   = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);
        try {
            await signInWithEmailAndPassword(auth, email, password);
            // onAuthStateChanged in App.js will handle the redirect automatically
        } catch (err) {
            setError('Incorrect email or password.');
            setLoading(false);
        }
    };

    return (
        <div className="login-page">
            <div className="login-card">
                <div className="login-logo">🧪</div>
                <h1 className="login-title">Jagdamba Pathology Lab</h1>
                <p className="login-subtitle">Staff sign-in</p>
                <form onSubmit={handleSubmit} autoComplete="on">
                    <div className="form-group">
                        <input
                            type="email"
                            className="form-control login-input"
                            placeholder="Email"
                            value={email}
                            onChange={e => setEmail(e.target.value)}
                            required
                            autoFocus
                            autoComplete="email"
                        />
                    </div>
                    <div className="form-group">
                        <input
                            type="password"
                            className="form-control login-input"
                            placeholder="Password"
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            required
                            autoComplete="current-password"
                        />
                    </div>
                    {error && (
                        <div className="alert alert-danger login-error">{error}</div>
                    )}
                    <button
                        type="submit"
                        className="btn btn-primary btn-block login-btn"
                        disabled={loading}
                    >
                        {loading ? 'Signing in…' : 'Sign In'}
                    </button>
                </form>
            </div>
        </div>
    );
}

export default Login;
