import React, {Component} from 'react';
import './App.css'
import {utils} from "../helper/utils";
import {reportUtils} from "../helper/reportUtils";

class Section extends Component {

    constructor(props) {
        super(props);
        this.sectionRef = React.createRef();
        this.state = {collapsed: true, bloodGroupDraft: {}};
    }

    componentDidUpdate(prevProps) {
        if (this.props.expandKey && this.props.expandKey !== prevProps.expandKey) {
            this.setState({collapsed: false});
        }
        if (this.props.collapseKey !== prevProps.collapseKey) {
            this.setState({collapsed: true});
        }
        // Clear blood group draft when section is fully cleared externally
        if (prevProps.patientReport !== this.props.patientReport &&
            !reportUtils.hasReportData(this.props.patientReport) &&
            Object.keys(this.state.bloodGroupDraft).length > 0) {
            this.setState({bloodGroupDraft: {}});
        }
    }

    toggleCollapse = () => {
        this.setState(prev => ({collapsed: !prev.collapsed}));
    };

    // Blur the input, scroll the section heading to the top (same as sidebar click),
    // then re-focus the input without triggering another browser scroll.
    scrollSectionToTopAndRefocus = (inputEl) => {
        const anchorId = this.props.id;
        inputEl.blur();
        const anchor = document.getElementById(anchorId);
        if (anchor) anchor.scrollIntoView({behavior: 'smooth', block: 'start'});
        setTimeout(() => inputEl.focus({ preventScroll: true }), 350);
    };

    handleKeyDown = (e) => {
        const navH = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--navbar-height')) || 60;
        const rect = e.target.getBoundingClientRect();
        const isOffScreen = rect.top > window.innerHeight || rect.bottom < navH;

        if (isOffScreen) {
            // The input is off-screen. Let the keypress complete (character is typed),
            // then blur → scroll section to top → re-focus. We blur first because Chrome
            // keeps the focused element in view and would fight any scrollIntoView otherwise.
            const target = e.target;
            setTimeout(() => this.scrollSectionToTopAndRefocus(target), 0);
        }

        if (e.key !== 'Enter') return;
        e.preventDefault();
        if (!this.sectionRef.current) return;
        const inputs = Array.from(this.sectionRef.current.querySelectorAll('input:not([disabled])'));
        const idx = inputs.indexOf(e.target);
        if (idx !== -1 && idx < inputs.length - 1) {
            // Advance within this section — just scroll enough to keep the next input visible,
            // not all the way to the section heading.
            const nextInput = inputs[idx + 1];
            nextInput.focus({ preventScroll: true });
            nextInput.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } else if (idx === inputs.length - 1 && this.props.onAdvanceSection) {
            // Last input in this section — jump to the next section (expands it if collapsed)
            this.props.onAdvanceSection(this.props.id);
        }
    };

    handleInputFocus = (e) => {};

    unitRangeCheck = (value, state, preview) => {
        let noUnit = true;
        let noRange = true;

        for (const row of value['data']) {
            if (row['unit'] && (!preview || (preview && reportUtils.isFilledValue(state[row['id']])))) {
                noUnit = false;
                break;
            }
        }

        for (const row of value['data']) {
            if (row['range'] && (!preview || (preview && reportUtils.isFilledValue(state[row['id']])))) {
                noRange = false;
                break;
            }
        }

        return {noUnit, noRange};
    };

    unitAndRangeWrapper = (placeholder, state = {}, preview = false) => {
        if (placeholder['sub_category']) {
            let noUnit = true;
            let noRange = true;

            for (const subCategory of placeholder['sub_category']) {
                const result = this.unitRangeCheck(subCategory, state, preview);
                noUnit = noUnit && result.noUnit;
                noRange = noRange && result.noRange;
            }

            return {noUnit, noRange};
        }

        return this.unitRangeCheck(placeholder, state, preview);
    };

    onChange = (e) => {
        const {name, value} = e.target;
        this.props.onPatientReportChanged(this.props.id, {[name]: value});
    };

    getRange = (item) => {
        if (item.type !== 'range') return '';

        const range = item.range;
        if (range['M'] && range['F']) {
            if (range['M']['lower'] && range['F']['lower']) {
                return utils.format(
                    'M({}-{}) F({}-{})',
                    range['M']['lower'], range['M']['higher'],
                    range['F']['lower'], range['F']['higher']);
            }

            return utils.format(
                'M(<{}) F(<{})',
                range['M']['higher'],
                range['F']['higher']);
        }

        if (range['lower'] !== undefined) {
            return utils.format('({}-{})', range['lower'], range['higher']);
        }

        return utils.format('< {}', range['higher']);
    };

    getUnit = (item) => {
        return item.unit ? item.unit : '';
    };

    getInput = (state, item, extras) => {
        const {id, type, values, auto_fill} = item;
        const value = state[id] === undefined || state[id] === null ? '' : state[id];
        const abnormalStatus = reportUtils.getAbnormalStatus(item, value, extras.gender);
        const bold = this.props.boldAbnormal !== false; // default true for back-compat
        const resultClass = (bold && abnormalStatus) ? 'result-input abnormal-result' : 'result-input';

        switch (type) {
            case 'range':
                if (auto_fill) {
                    const cls = (bold && abnormalStatus) ? 'computed-value abnormal-result' : 'computed-value';
                    return <span className={cls}>
                        {reportUtils.isFilledValue(value)
                            ? value
                            : <span className="autocomputed-hint">Autocomputed</span>}
                    </span>;
                }

                return <input name={id}
                              type='number'
                              onChange={this.onChange}
                              onKeyDown={this.handleKeyDown}
                              onFocus={this.handleInputFocus}
                              className={resultClass}
                              value={value}
                />;
            case 'free':
                if (auto_fill) {
                    return <span className='computed-value'>
                        {reportUtils.isFilledValue(value)
                            ? value
                            : <span className="autocomputed-hint">Autocomputed</span>}
                    </span>;
                }

                return <input
                    name={id}
                    type='text'
                    onChange={this.onChange}
                    onKeyDown={this.handleKeyDown}
                    onFocus={this.handleInputFocus}
                    className='result-input'
                    value={value}
                />;
            case 'radio': {
                const selected = value || reportUtils.EMPTY_SELECT_VALUE;
                const optionValues = values.filter(v => v !== reportUtils.EMPTY_SELECT_VALUE);

                if (this.props.preview) {
                    return <span className="computed-value">{selected !== reportUtils.EMPTY_SELECT_VALUE ? selected : ''}</span>;
                }

                if (optionValues.length <= 8) {
                    const isBloodGroup = optionValues.length === 8 &&
                        optionValues.every(v => /^(AB|A|B|O)[+-]$/.test(v));

                    if (isBloodGroup) {
                        const draft = this.state.bloodGroupDraft[id];
                        let displayType = null, displayRh = null;
                        if (draft) {
                            displayType = draft.type;
                            displayRh = draft.rh;
                        } else if (selected !== reportUtils.EMPTY_SELECT_VALUE) {
                            displayRh = selected.slice(-1);
                            displayType = selected.slice(0, -1);
                        }

                        const handleBloodClick = (part, clickedVal) => {
                            const newType = part === 'type' ? (displayType === clickedVal ? null : clickedVal) : displayType;
                            const newRh   = part === 'rh'   ? (displayRh   === clickedVal ? null : clickedVal) : displayRh;
                            if (newType && newRh) {
                                this.props.onPatientReportChanged(this.props.id, {[id]: `${newType}${newRh}`});
                                this.setState(prev => {
                                    const d = {...prev.bloodGroupDraft};
                                    delete d[id];
                                    return {bloodGroupDraft: d};
                                });
                            } else {
                                if (reportUtils.isFilledValue(value)) {
                                    this.props.onPatientReportChanged(this.props.id, {[id]: reportUtils.EMPTY_SELECT_VALUE});
                                }
                                this.setState(prev => ({
                                    bloodGroupDraft: {...prev.bloodGroupDraft, [id]: {type: newType, rh: newRh}}
                                }));
                            }
                        };

                        return (
                            <div className="blood-group-selector">
                                <div className="option-group">
                                    {['A', 'B', 'AB', 'O'].map(t => (
                                        <button key={t} type="button"
                                            data-color-intent="blood-group"
                                            className={`option-btn${displayType === t ? ' option-btn--selected' : ''}`}
                                            onClick={() => handleBloodClick('type', t)}
                                        >{t}</button>
                                    ))}
                                </div>
                                <div className="option-group">
                                    {['+', '-'].map(r => (
                                        <button key={r} type="button"
                                            data-color-intent={r === '+' ? 'positive' : 'negative'}
                                            className={`option-btn${displayRh === r ? ' option-btn--selected' : ''}`}
                                            onClick={() => handleBloodClick('rh', r)}
                                        >{r}</button>
                                    ))}
                                </div>
                            </div>
                        );
                    }

                    return (
                        <div className="option-group">
                            {optionValues.map(opt => (
                                <button
                                    key={opt}
                                    type="button"
                                    data-color-intent={reportUtils.getOptionColorIntent(opt)}
                                    className={`option-btn${selected === opt ? ' option-btn--selected' : ''}`}
                                    onClick={() => {
                                        const next = selected === opt ? reportUtils.EMPTY_SELECT_VALUE : opt;
                                        this.props.onPatientReportChanged(this.props.id, {[id]: next});
                                    }}
                                >{opt}</button>
                            ))}
                        </div>
                    );
                }

                return <select name={id}
                               onChange={this.onChange}
                               className='result-input'
                               value={selected}>
                    {values.map((val, i) => <option key={i} value={val}>{val}</option>)}
                </select>;
            }
            default:
                return <div/>;
        }
    };

    getAbnormalBadge = (state, item, extras) => {
        if (!this.props.showAbnormalBadges) return null;
        const status = reportUtils.getAbnormalStatus(item, state[item.id], extras.gender);
        if (!status) return null;

        return <span className={`abnormal-badge abnormal-${status}`}>{status === 'high' ? 'High' : 'Low'}</span>;
    };

    getRow = (state, head, data, extras, noRange, noUnit) => {
        const preview = this.props.preview;
        const allEmpty = data.every(item => preview && !reportUtils.isFilledValue(state[item.id]));

        return <tbody key={head || 'body'}>
        {head && <tr hidden={allEmpty}>
            <th colSpan='4' scope='colgroup'>{head}</th>
        </tr>}
        {data && data.map(item => {
            const hidden = preview && !reportUtils.isFilledValue(state[item.id]);
            const abnormalStatus = reportUtils.getAbnormalStatus(item, state[item.id], extras.gender);
            const boldRow = this.props.boldAbnormal !== false;
            return <tr hidden={hidden} key={item.id}>
                <td>{item.name}</td>
                <td className={`result-cell${(boldRow && abnormalStatus) ? ' result-cell--abnormal' : ''}`}>
                    {this.getInput(state, item, extras)}
                    {this.getAbnormalBadge(state, item, extras)}
                </td>
                {!noUnit && <td>{this.getUnit(item)}</td>}
                {!noRange && <td>{this.getRange(item)}</td>}
            </tr>;
        })}
        </tbody>;
    };

    onClear = () => {
        this.props.onClear(this.props.id);
    };

    render() {
        const {name, sub_category, data} = this.props.placeholder;
        const preview = this.props.preview;
        const extras = this.props.extras;
        const state = this.props.patientReport || {};
        const sectionIsEmpty = !reportUtils.hasReportData(state);
        const {noRange, noUnit} = this.unitAndRangeWrapper(this.props.placeholder, state, preview);
        const isCollapsed = !preview && this.state.collapsed;

        return (
            <section ref={this.sectionRef} hidden={preview && sectionIsEmpty} className='report-section no-page-break'>
                <span id={this.props.id} className='anchor'/>
                <div className="section-heading">
                    {!preview
                        ? <button className="section-heading-toggle" onClick={this.toggleCollapse}>
                            <h4>{name}</h4>
                            <span className="collapse-icon">{isCollapsed ? '▶' : '▼'}</span>
                          </button>
                        : <h4>{name}</h4>
                    }
                    {!preview && <button title="Clear this report" className='btn btn-sm btn-outline-danger'
                                         onClick={this.onClear}>Clear section</button>}
                </div>
                {!isCollapsed && <table
                    className={preview ? 'report-table' : 'table table-bordered report-table'}
                    data-cols={2 + (noUnit ? 0 : 1) + (noRange ? 0 : 1)}>
                    <colgroup>
                        <col className="col-test-name" />
                        <col className="col-result" />
                        {!noUnit && <col className="col-unit" />}
                        {!noRange && <col className="col-range" />}
                    </colgroup>
                    <thead className={preview ? '' : 'thead-dark'}>
                    <tr>
                        <th>Test Name</th>
                        <th>Result</th>
                        {!noUnit && <th>Unit</th>}
                        {!noRange && <th>Ref Range</th>}
                    </tr>
                    </thead>
                    {sub_category ?
                        sub_category.map((subCategory) => {
                            return this.getRow(state, subCategory.name, subCategory.data, extras, noRange, noUnit)
                        })
                        :
                        this.getRow(state, null, data, extras, noRange, noUnit)
                    }
                </table>}
            </section>
        );
    }
}

export default Section;
