const EMPTY_SELECT_VALUE = 'Not selected';

export function isFilledValue(value) {
    if (value === undefined || value === null || value === '' || value === EMPTY_SELECT_VALUE) {
        return false;
    }

    if (typeof value === 'object') {
        return Object.values(value).some(isFilledValue);
    }

    return true;
}

export function hasReportData(report = {}) {
    return Object.values(report || {}).some(isFilledValue);
}

export function getSectionRows(placeholder = {}) {
    if (placeholder.sub_category) {
        return placeholder.sub_category.reduce((rows, category) => rows.concat(category.data || []), []);
    }

    return placeholder.data || [];
}

function parseFormula(expression) {
    let index = 0;

    function skipSpaces() {
        while (expression[index] === ' ') {
            index += 1;
        }
    }

    function parseNumber() {
        skipSpaces();
        let start = index;

        if (expression[index] === '-') {
            index += 1;
        }

        while (/[0-9.]/.test(expression[index])) {
            index += 1;
        }

        if (start === index || (expression[start] === '-' && start + 1 === index)) {
            throw new Error('Expected number');
        }

        const value = Number(expression.slice(start, index));
        if (!Number.isFinite(value)) {
            throw new Error('Invalid number');
        }

        return value;
    }

    function parseFactor() {
        skipSpaces();

        if (expression[index] === '(') {
            index += 1;
            const value = parseAddSub();
            skipSpaces();
            if (expression[index] !== ')') {
                throw new Error('Expected closing parenthesis');
            }
            index += 1;
            return value;
        }

        return parseNumber();
    }

    function parseMulDiv() {
        let value = parseFactor();

        while (true) {
            skipSpaces();
            const operator = expression[index];
            if (operator !== '*' && operator !== '/') {
                break;
            }

            index += 1;
            const nextValue = parseFactor();
            value = operator === '*' ? value * nextValue : value / nextValue;
        }

        return value;
    }

    function parseAddSub() {
        let value = parseMulDiv();

        while (true) {
            skipSpaces();
            const operator = expression[index];
            if (operator !== '+' && operator !== '-') {
                break;
            }

            index += 1;
            const nextValue = parseMulDiv();
            value = operator === '+' ? value + nextValue : value - nextValue;
        }

        return value;
    }

    const result = parseAddSub();
    skipSpaces();

    if (index !== expression.length || !Number.isFinite(result)) {
        throw new Error('Invalid formula');
    }

    return result;
}

export function evaluateFormula(expression, state = {}) {
    if (!expression) {
        return '';
    }

    const requiredIds = expression.match(/{\d+}/g) || [];
    let replaced = expression;

    for (const requiredId of requiredIds) {
        const id = requiredId.slice(1, -1);
        const value = state[id];
        if (!isFilledValue(value)) {
            return '';
        }
        replaced = replaced.replace(new RegExp('\\{' + id + '\\}', 'g'), value);
    }

    if (!/^[0-9+\-*/().\s]+$/.test(replaced)) {
        throw new Error('Formula contains unsupported characters');
    }

    return Math.round(parseFormula(replaced) * 100) / 100;
}

export function applyAutoFill(placeholder, report = {}) {
    const rows = getSectionRows(placeholder);
    const autoRows = rows.filter(row => row.auto_fill);
    const result = {...report};

    autoRows.forEach(row => {
        try {
            result[row.id] = evaluateFormula(row.auto_fill, result);
        } catch (e) {
            result[row.id] = '';
        }
    });

    return result;
}

export function getRangeForGender(item, gender) {
    if (!item || !item.range) {
        return null;
    }

    if (item.range.M && item.range.F) {
        return item.range[gender] || null;
    }

    return item.range;
}

export function getAbnormalStatus(item, value, gender) {
    if (!item || item.type !== 'range' || !isFilledValue(value)) {
        return null;
    }

    const range = getRangeForGender(item, gender);
    const numericValue = Number(value);
    if (!range || !Number.isFinite(numericValue)) {
        return null;
    }

    const lower = range.lower !== undefined ? Number(range.lower) : null;
    const higher = range.higher !== undefined ? Number(range.higher) : null;

    if (lower !== null && Number.isFinite(lower) && numericValue < lower) {
        return 'low';
    }

    if (higher !== null && Number.isFinite(higher) && numericValue > higher) {
        return 'high';
    }

    return null;
}

export function validateReportState(patientInfo = {}, patientReport = {}) {
    const messages = [];

    if (!patientInfo.name) {
        messages.push('Patient name is missing.');
    }

    if (!patientInfo.age) {
        messages.push('Age is missing.');
    }

    if (!patientInfo.gender || patientInfo.gender === EMPTY_SELECT_VALUE) {
        messages.push('Sex is not selected.');
    }

    if (!patientInfo.labNumber) {
        messages.push('Lab number is missing.');
    }

    if (!patientInfo.date) {
        messages.push('Date is missing.');
    }

    const hasAnyReport = Object.values(patientReport || {}).some(hasReportData);
    if (!hasAnyReport) {
        messages.push('At least one report section needs a result.');
    }

    return messages;
}

export function createSavedPayload(state) {
    return {
        patientInfo: state.patientInfo,
        patientReport: state.patientReport,
        savedAt: new Date().toISOString()
    };
}

export function getOptionColorIntent(value) {
    const v = (value || '').toLowerCase().trim();
    if (v === 'positive' || v === '+') return 'positive';
    if (v === 'negative' || v === '-') return 'negative';
    if (v === 'nil' || v === 'not present' || v === 'not seen') return 'nil';
    if (v === 'trace' || v === 'slighty trace') return 'grade-trace';
    if (v === '(+)' || v === '(+) present') return 'grade-1';
    if (v === '(++)' || v === '(++) present') return 'grade-2';
    if (v === '(+++)' || v === '(+++) present') return 'grade-3';
    if (v === '(++++)') return 'grade-4';
    if (v === 'clear') return 'positive';
    if (v === 'slightly turbid') return 'grade-2';
    if (v === 'turbid') return 'grade-3';
    if (v.includes('seen') && v !== 'not seen') return 'grade-3';
    if (v === 'loose') return 'grade-2';
    // blood groups
    if (/^(a|b|ab|o)[+-]$/.test(v)) return 'blood-group';
    // colour-named options
    if (v.includes('yellow') || v === 'straw') return 'yellowish';
    if (v.includes('brown')) return 'brownish';
    if (v.includes('green')) return 'greenish';
    if (v.includes('red') || v === 'reddish') return 'reddish';
    return null;
}

export const reportUtils = {
    EMPTY_SELECT_VALUE,
    applyAutoFill,
    createSavedPayload,
    evaluateFormula,
    getAbnormalStatus,
    getOptionColorIntent,
    getRangeForGender,
    getSectionRows,
    hasReportData,
    isFilledValue,
    validateReportState,
};
