const SETTINGS_KEY = 'jagdambaLabSettings';

export const SETTINGS_DEFAULTS = {
    hideHighLowChips: false,          // Display > Show H/L label
    boldAbnormal: true,               // Display > Bold abnormal values
    saveToCloud: true,                // Storage > Auto-save to cloud
    showQrInPdf: true,                // PDF > Show QR code
    pdfMargin: { top: 10, bottom: 10, left: 13, right: 13 }, // mm
    tableCellPadding: { vertical: 2, horizontal: 4 },          // pt (PDF cells)
    tableSpacing: 8,                  // pt between tables in PDF
    signature: '',                    // legacy single footer text (kept for compat)
    signatureLeft: '',                // PDF > Left signature block (multiline)
    signatureRight: '',               // PDF > Right signature block (multiline)
    showSignatureLeft: true,          // PDF > Show left signature
    showSignatureRight: true,         // PDF > Show right signature
    fontSizes: {
        body: 8,            // table cells, patient info, signature text
        sectionHeading: 9,  // e.g. "HAEMATOLOGY"
        labName: 13,        // "JAGDAMBA PATHOLOGY LAB"
        endOfReport: 8,     // "** END OF REPORT **"
        qrLabel: 7,         // "Scan to view report"
    },
};

export function loadSettings() {
    try {
        const raw = localStorage.getItem(SETTINGS_KEY);
        if (!raw) return {
            ...SETTINGS_DEFAULTS,
            pdfMargin: { ...SETTINGS_DEFAULTS.pdfMargin },
            tableCellPadding: { ...SETTINGS_DEFAULTS.tableCellPadding },
        };
        const stored = JSON.parse(raw);
        return {
            ...SETTINGS_DEFAULTS,
            ...stored,
            pdfMargin: { ...SETTINGS_DEFAULTS.pdfMargin, ...(stored.pdfMargin || {}) },
            tableCellPadding: { ...SETTINGS_DEFAULTS.tableCellPadding, ...(stored.tableCellPadding || {}) },
            fontSizes: { ...SETTINGS_DEFAULTS.fontSizes, ...(stored.fontSizes || {}) },
        };
    } catch (e) {
        return {
            ...SETTINGS_DEFAULTS,
            pdfMargin: { ...SETTINGS_DEFAULTS.pdfMargin },
            tableCellPadding: { ...SETTINGS_DEFAULTS.tableCellPadding },
        };
    }
}

export function saveSettings(settings) {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
}
