import React from 'react';
import {NepaliDatePicker as Picker} from 'nepali-datepicker-reactjs';
import 'nepali-datepicker-reactjs/dist/index.css';

/**
 * Thin wrapper around nepali-datepicker-reactjs.
 * Renders plain text in preview/print mode.
 */
const NepaliDatePicker = ({value, onChange, preview, className}) => {
    if (preview) {
        return <span>{value}</span>;
    }

    return (
        <Picker
            inputClassName={`nepali-date-input${className ? ' ' + className : ''}`}
            className="nepali-date-wrapper"
            value={value || ''}
            onChange={onChange}
            options={{calenderLocale: 'en', valueLocale: 'en'}}
        />
    );
};

export default NepaliDatePicker;
